// router.use('/pages', pageRoutes);
// router.use('/memory-db', memoryDbRoutes);

module.exports = router;

/**
 * Utility functions for creating and manipulating Notion blocks
 */

/**
 * Checks if content is already in Notion block format
 * @param {*} content - Content to check
 * @returns {boolean} True if content is in block format
 */
const isBlockFormat = (content) => {
  return Array.isArray(content) && 
         content.length > 0 && 
         content.every(item => typeof item === 'object' && item.type);
};

/**
 * Processes content into Notion blocks if not already in block format
 * @param {string|Array} content - Content to process
 * @returns {Array} Content in block format
 */
const processIntoBlocks = (content) => {
  if (isBlockFormat(content)) {
    return content;
  }

  if (Array.isArray(content)) {
    return content.map(item => {
      if (typeof item === 'string') {
        return createParagraphBlock(item);
      }
      return item;
    });
  }

  if (typeof content === 'string') {
    // Split by double newlines to get paragraphs
    const paragraphs = content.split('\n\n');
    return paragraphs.map(p => createParagraphBlock(p.trim()));
  }

  return [];
};

/**
 * Creates a paragraph block
 * @param {string} text - Text content
 * @returns {Object} Paragraph block
 */
const createParagraphBlock = (text) => {
  return {
    type: 'paragraph',
    paragraph: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }]
    }
  };
};

/**
 * Creates a heading block
 * @param {string} text - Heading text
 * @param {number} level - Heading level (1-3)
 * @returns {Object} Heading block
 */
const createHeadingBlock = (text, level = 1) => {
  const validLevel = Math.min(Math.max(1, level), 3);
  const headingType = `heading_${validLevel}`;

  return {
    type: headingType,
    [headingType]: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }]
    }
  };
};

/**
 * Creates a bulleted list item block
 * @param {string} text - List item text
 * @returns {Object} Bulleted list item block
 */
const createBulletedListItemBlock = (text) => {
  return {
    type: 'bulleted_list_item',
    bulleted_list_item: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }]
    }
  };
};

/**
 * Creates a numbered list item block
 * @param {string} text - List item text
 * @returns {Object} Numbered list item block
 */
const createNumberedListItemBlock = (text) => {
  return {
    type: 'numbered_list_item',
    numbered_list_item: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }]
    }
  };
};

/**
 * Creates a to-do list item block
 * @param {string} text - Task text
 * @param {boolean} checked - Whether the task is checked
 * @returns {Object} To-do list item block
 */
const createToDoBlock = (text, checked = false) => {
  return {
    type: 'to_do',
    to_do: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }],
      checked
    }
  };
};

/**
 * Creates a code block
 * @param {string} code - Code content
 * @param {string} language - Programming language
 * @returns {Object} Code block
 */
const createCodeBlock = (code, language = 'javascript') => {
  return {
    type: 'code',
    code: {
      rich_text: [{
        type: 'text',
        text: { content: code }
      }],
      language
    }
  };
};

/**
 * Creates a quote block
 * @param {string} text - Quote text
 * @returns {Object} Quote block
 */
const createQuoteBlock = (text) => {
  return {
    type: 'quote',
    quote: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }]
    }
  };
};

/**
 * Creates a divider block
 * @returns {Object} Divider block
 */
const createDividerBlock = () => {
  return {
    type: 'divider',
    divider: {}
  };
};

/**
 * Creates a toggle block
 * @param {string} text - Toggle text
 * @returns {Object} Toggle block
 */
const createToggleBlock = (text) => {
  return {
    type: 'toggle',
    toggle: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }],
      children: []
    }
  };
};

/**
 * Creates a callout block
 * @param {string} text - Callout text
 * @param {string} emoji - Emoji icon
 * @returns {Object} Callout block
 */
const createCalloutBlock = (text, emoji = '💡') => {
  return {
    type: 'callout',
    callout: {
      rich_text: [{
        type: 'text',
        text: { content: text }
      }],
      icon: {
        type: 'emoji',
        emoji
      }
    }
  };
};

/**
 * Creates an image block from a URL
 * @param {string} url - Image URL
 * @param {string} caption - Optional image caption
 * @returns {Object} Image block
 */
const createImageBlock = (url, caption = '') => {
  const block = {
    type: 'image',
    image: {
      type: 'external',
      external: {
        url
      }
    }
  };

  if (caption) {
    block.image.caption = [{
      type: 'text',
      text: { content: caption }
    }];
  }

  return block;
};

/**
 * Adds children to a block that supports children
 * @param {Object} block - Parent block
 * @param {Array} children - Child blocks
 * @returns {Object} Block with children
 */
const addChildrenToBlock = (block, children) => {
  if (!block || !children || !Array.isArray(children)) {
    return block;
  }

  const blockCopy = { ...block };
  const blockType = blockCopy.type;

  // Not all block types can have children in Notion
  const supportedParentTypes = ['toggle', 'paragraph', 'bulleted_list_item', 'numbered_list_item'];

  if (!supportedParentTypes.includes(blockType)) {
    return block;
  }

  if (!blockCopy[blockType].children) {
    blockCopy[blockType].children = [];
  }

  blockCopy[blockType].children = [
    ...blockCopy[blockType].children,
    ...processIntoBlocks(children)
  ];

  return blockCopy;
};

/**
 * Creates a block with rich text formatting
 * @param {string} type - Block type
 * @param {Array} richTextArray - Array of rich text objects
 * @returns {Object} Block with rich text
 */
const createRichTextBlock = (type, richTextArray) => {
  return {
    type,
    [type]: {
      rich_text: richTextArray
    }
  };
};

/**
 * Creates a rich text object with text content
 * @param {string} content - Text content
 * @param {Object} annotations - Text annotations (bold, italic, etc.)
 * @returns {Object} Rich text object
 */
const createRichText = (content, annotations = {}) => {
  return {
    type: 'text',
    text: { content },
    annotations: {
      bold: annotations.bold || false,
      italic: annotations.italic || false,
      strikethrough: annotations.strikethrough || false,
      underline: annotations.underline || false,
      code: annotations.code || false,
      color: annotations.color || 'default'
    }
  };
};

module.exports = {
  // Block detection and processing
  isBlockFormat,
  processIntoBlocks,

  // Block creation functions
  createParagraphBlock,
  createHeadingBlock,
  createBulletedListItemBlock,
  createNumberedListItemBlock,
  createToDoBlock,
  createCodeBlock,
  createQuoteBlock,
  createDividerBlock,
  createToggleBlock,
  createCalloutBlock,
  createImageBlock,

  // Block manipulation
  addChildrenToBlock,

  // Rich text utilities
  createRichText,
  createRichTextBlock
};

/**
 * Utility functions for creating and manipulating Notion blocks
 */

/**
 * Checks if content is already in Notion block format
 * @param {*} content - Content to check
 * @returns {boolean} True if content is in block format
 */
const isBlockFormat = (content) => {
  return Array.isArray(content) && 
         content.length > 0 && 
         content.every(item => typeof item === 'object' && item.type);
};

/**
 * Processes content into Notion blocks if not already in block format
 * @param {string|Array} content - Content to process
 * @returns {Array} Content in block format
 */
const processIntoBlocks = (content) => {
  if (isBlockFormat(content)) {
    return content;
  }

  if (Array.isArray(content)) {
    return content.map(item => {
      if (typeof item === 'string') {
        return createParagraphBlock(item);
      }
      return item;
    });
  }

  if (typeof content === 'string') {
    // Split by double newlines to get paragraphs
    const paragraphs = content.split(/\n\n+/);
    return paragraphs
      .filter(p => p.trim().length > 0)
      .map(p => createParagraphBlock(p.trim()));
  }

  return [];
};

/**
 * Creates a rich text object
 * @param {string} content - Text content
 * @param {Object} annotations - Optional annotations for formatting
 * @returns {Object} Rich text object
 */
const createRichText = (content, annotations = {}) => {
  return {
    type: 'text',
    text: { content },
    annotations: {
      bold: annotations.bold || false,
      italic: annotations.italic || false,
      strikethrough: annotations.strikethrough || false,
      underline: annotations.underline || false,
      code: annotations.code || false,
      color: annotations.color || 'default'
    }
  };
};

/**
 * Converts a string or array of strings to rich text array
 * @param {string|Array} text - Text content or array of rich text objects
 * @returns {Array} Array of rich text objects
 */
const toRichTextArray = (text) => {
  if (!text) return [];

  if (Array.isArray(text)) {
    if (text.length === 0) return [];
    // If already rich text array format, return as is
    if (text[0].type && text[0].text) return text;
    // Convert array of strings to rich text objects
    return text.map(t => createRichText(String(t)));
  }

  return [createRichText(String(text))];
};

/**
 * Creates a paragraph block
 * @param {string|Array} text - Text content or rich text array
 * @returns {Object} Paragraph block
 */
const createParagraphBlock = (text) => {
  return {
    type: 'paragraph',
    paragraph: {
      rich_text: toRichTextArray(text)
    }
  };
};

/**
 * Creates a heading block
 * @param {string|Array} text - Heading text or rich text array
 * @param {number} level - Heading level (1-3)
 * @returns {Object} Heading block
 */
const createHeadingBlock = (text, level = 1) => {
  const validLevel = Math.min(Math.max(1, level), 3);
  const headingType = `heading_${validLevel}`;

  return {
    type: headingType,
    [headingType]: {
      rich_text: toRichTextArray(text)
    }
  };
};

/**
 * Creates a bulleted list item block
 * @param {string|Array} text - List item text or rich text array
 * @param {Array} children - Optional children blocks
 * @returns {Object} Bulleted list item block
 */
const createBulletedListItemBlock = (text, children = []) => {
  const block = {
    type: 'bulleted_list_item',
    bulleted_list_item: {
      rich_text: toRichTextArray(text)
    }
  };

  if (children.length > 0) {
    block.bulleted_list_item.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a numbered list item block
 * @param {string|Array} text - List item text or rich text array
 * @param {Array} children - Optional children blocks
 * @returns {Object} Numbered list item block
 */
const createNumberedListItemBlock = (text, children = []) => {
  const block = {
    type: 'numbered_list_item',
    numbered_list_item: {
      rich_text: toRichTextArray(text)
    }
  };

  if (children.length > 0) {
    block.numbered_list_item.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a to-do list item block
 * @param {string|Array} text - Task text or rich text array
 * @param {boolean} checked - Whether the task is checked
 * @param {Array} children - Optional children blocks
 * @returns {Object} To-do list item block
 */
const createToDoBlock = (text, checked = false, children = []) => {
  const block = {
    type: 'to_do',
    to_do: {
      rich_text: toRichTextArray(text),
      checked
    }
  };

  if (children.length > 0) {
    block.to_do.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a code block
 * @param {string} code - Code content
 * @param {string} language - Programming language
 * @returns {Object} Code block
 */
const createCodeBlock = (code, language = 'javascript') => {
  return {
    type: 'code',
    code: {
      rich_text: toRichTextArray(code),
      language
    }
  };
};

/**
 * Creates a quote block
 * @param {string|Array} text - Quote text or rich text array
 * @param {Array} children - Optional children blocks
 * @returns {Object} Quote block
 */
const createQuoteBlock = (text, children = []) => {
  const block = {
    type: 'quote',
    quote: {
      rich_text: toRichTextArray(text)
    }
  };

  if (children.length > 0) {
    block.quote.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a divider block
 * @returns {Object} Divider block
 */
const createDividerBlock = () => {
  return {
    type: 'divider',
    divider: {}
  };
};

/**
 * Creates a callout block
 * @param {string|Array} text - Callout text or rich text array
 * @param {string} emoji - Emoji icon
 * @param {string} color - Color of the callout
 * @param {Array} children - Optional children blocks
 * @returns {Object} Callout block
 */
const createCalloutBlock = (text, emoji = '💡', color = 'default', children = []) => {
  const block = {
    type: 'callout',
    callout: {
      rich_text: toRichTextArray(text),
      icon: {
        type: 'emoji',
        emoji
      },
      color
    }
  };

  if (children.length > 0) {
    block.callout.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a toggle block
 * @param {string|Array} text - Toggle text or rich text array
 * @param {Array} children - Child blocks inside the toggle
 * @returns {Object} Toggle block
 */
const createToggleBlock = (text, children = []) => {
  const block = {
    type: 'toggle',
    toggle: {
      rich_text: toRichTextArray(text)
    }
  };

  if (children.length > 0) {
    block.toggle.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates an image block from a URL
 * @param {string} url - Image URL
 * @param {string|Array} caption - Optional image caption or rich text array
 * @returns {Object} Image block
 */
const createImageBlock = (url, caption = '') => {
  const block = {
    type: 'image',
    image: {
      type: 'external',
      external: {
        url
      }
    }
  };

  if (caption) {
    block.image.caption = toRichTextArray(caption);
  }

  return block;
};

/**
 * Creates a bookmark block
 * @param {string} url - Bookmark URL
 * @param {string|Array} caption - Optional caption or rich text array
 * @returns {Object} Bookmark block
 */
const createBookmarkBlock = (url, caption = '') => {
  const block = {
    type: 'bookmark',
    bookmark: {
      url
    }
  };

  if (caption) {
    block.bookmark.caption = toRichTextArray(caption);
  }

  return block;
};

/**
 * Creates an equation block with LaTeX content
 * @param {string} latex - LaTeX expression
 * @returns {Object} Equation block
 */
const createEquationBlock = (latex) => {
  return {
    type: 'equation',
    equation: {
      expression: latex
    }
  };
};

/**
 * Creates a table block
 * @param {number} columnCount - Number of columns
 * @param {Array} rows - Array of row data (each row is an array of strings or rich text arrays)
 * @param {boolean} hasColumnHeader - Whether the first row is a header
 * @param {boolean} hasRowHeader - Whether the first column is a header
 * @returns {Object} Table block with children
 */
const createTableBlock = (columnCount, rows, hasColumnHeader = true, hasRowHeader = false) => {
  if (!Array.isArray(rows) || rows.length === 0) {
    return null;
  }

  const tableBlock = {
    type: 'table',
    table: {
      table_width: columnCount,
      has_column_header: hasColumnHeader,
      has_row_header: hasRowHeader,
      children: []
    }
  };

  // Create table rows
  rows.forEach(rowData => {
    if (Array.isArray(rowData)) {
      const row = {
        type: 'table_row',
        table_row: {
          cells: rowData.map(cell => toRichTextArray(cell))
        }
      };
      tableBlock.table.children.push(row);
    }
  });

  return tableBlock;
};

/**
 * Creates a table of contents block
 * @param {string} color - Color of the table of contents
 * @returns {Object} Table of contents block
 */
const createTableOfContentsBlock = (color = 'default') => {
  return {
    type: 'table_of_contents',
    table_of_contents: { color }
  };
};

/**
 * Creates a breadcrumb block
 * @returns {Object} Breadcrumb block
 */
const createBreadcrumbBlock = () => {
  return {
    type: 'breadcrumb',
    breadcrumb: {}
  };
};

/**
 * Adds children to a block that supports children
 * @param {Object} block - Parent block
 * @param {Array} children - Child blocks
 * @returns {Object} Block with children
 */
const addChildrenToBlock = (block, children) => {
  if (!block || !children || !Array.isArray(children) || children.length === 0) {
    return block;
  }

  const blockCopy = JSON.parse(JSON.stringify(block));
  const blockType = blockCopy.type;

  // Not all block types can have children in Notion
  const supportedParentTypes = [
    'paragraph', 
    'bulleted_list_item', 
    'numbered_list_item', 
    'toggle', 
    'to_do',
    'quote',
    'callout',
    'column',
    'column_list',
    'template',
    'synced_block',
    'table'
  ];

  if (!supportedParentTypes.includes(blockType)) {
    return block;
  }

  if (!blockCopy[blockType].children) {
    blockCopy[blockType].children = [];
  }

  blockCopy[blockType].children = [
    ...blockCopy[blockType].children,
    ...processIntoBlocks(children)
  ];

  return blockCopy;
};

/**
 * Creates a column list block with columns
 * @param {Array} columnContents - Array of arrays, each sub-array contains blocks for one column
 * @returns {Object} Column list block with column children
 */
const createColumnListBlock = (columnContents) => {
  if (!Array.isArray(columnContents) || columnContents.length === 0) {
    return null;
  }

  const columnList = {
    type: 'column_list',
    column_list: {
      children: []
    }
  };

  // Create column blocks
  columnContents.forEach(columnBlocks => {
    const column = {
      type: 'column',
      column: {
        children: processIntoBlocks(columnBlocks)
      }
    };
    columnList.column_list.children.push(column);
  });

  return columnList;
};

/**
 * Creates a template block
 * @param {string|Array} text - Template text or rich text array
 * @param {Array} children - Child blocks for the template
 * @returns {Object} Template block
 */
const createTemplateBlock = (text, children = []) => {
  const block = {
    type: 'template',
    template: {
      rich_text: toRichTextArray(text)
    }
  };

  if (children.length > 0) {
    block.template.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a synced block
 * @param {string} syncedFrom - Block ID to sync from (null for original synced block)
 * @param {Array} children - Child blocks (only used for original synced blocks)
 * @returns {Object} Synced block
 */
const createSyncedBlock = (syncedFrom = null, children = []) => {
  const block = {
    type: 'synced_block',
    synced_block: {}
  };

  if (syncedFrom) {
    // This is a synced copy that references an original
    block.synced_block.synced_from = {
      type: 'block_id',
      block_id: syncedFrom
    };
  } else {
    // This is an original synced block
    block.synced_block.children = processIntoBlocks(children);
  }

  return block;
};

/**
 * Creates a link_to_page block that links to a page
 * @param {string} pageId - ID of the page to link to
 * @returns {Object} Link to page block
 */
const createLinkToPageBlock = (pageId) => {
  return {
    type: 'link_to_page',
    link_to_page: {
      type: 'page_id',
      page_id: pageId
    }
  };
};

/**
 * Creates a link preview block
 * @param {string} url - URL to preview
 * @returns {Object} Link preview block
 */
const createLinkPreviewBlock = (url) => {
  return {
    type: 'link_preview',
    link_preview: {
      url
    }
  };
};

/**
 * Creates an embed block
 * @param {string} url - URL to embed
 * @returns {Object} Embed block
 */
const createEmbedBlock = (url) => {
  return {
    type: 'embed',
    embed: {
      url
    }
  };
};

/**
 * Creates a video block from a URL
 * @param {string} url - Video URL
 * @param {string|Array} caption - Optional caption
 * @returns {Object} Video block
 */
const createVideoBlock = (url, caption = '') => {
  const block = {
    type: 'video',
    video: {
      type: 'external',
      external: {
        url
      }
    }
  };

  if (caption) {
    block.video.caption = toRichTextArray(caption);
  }

  return block;
};

/**
 * Creates a PDF block from a URL
 * @param {string} url - PDF URL
 * @param {string|Array} caption - Optional caption
 * @returns {Object} PDF block
 */
const createPdfBlock = (url, caption = '') => {
  const block = {
    type: 'pdf',
    pdf: {
      type: 'external',
      external: {
        url
      }
    }
  };

  if (caption) {
    block.pdf.caption = toRichTextArray(caption);
  }

  return block;
};

/**
 * Creates a file block from a URL
 * @param {string} url - File URL
 * @param {string} name - File name
 * @returns {Object} File block
 */
const createFileBlock = (url, name) => {
  return {
    type: 'file',
    file: {
      type: 'external',
      external: {
        url
      },
      caption: name ? toRichTextArray(name) : []
    }
  };
};

module.exports = {
  // Block detection and processing
  isBlockFormat,
  processIntoBlocks,

  // Rich text helpers
  createRichText,
  toRichTextArray,

  // Basic blocks
  createParagraphBlock,
  createHeadingBlock,
  createBulletedListItemBlock,
  createNumberedListItemBlock,
  createToDoBlock,
  createCodeBlock,
  createQuoteBlock,
  createDividerBlock,
  createToggleBlock,
  createCalloutBlock,

  // Media blocks
  createImageBlock,
  createVideoBlock,
  createFileBlock,
  createPdfBlock,
  createEmbedBlock,

  // Complex blocks
  createBookmarkBlock,
  createEquationBlock,
  createTableBlock,
  createTableOfContentsBlock,
  createBreadcrumbBlock,
  createColumnListBlock,
  createTemplateBlock,
  createSyncedBlock,
  createLinkToPageBlock,
  createLinkPreviewBlock,

  // Block manipulation
  addChildrenToBlock
};

