/**
 * page-utils.js
 * Utility functions for working with Notion pages
 */

const { NotionClient } = require('./api');

/**
 * Extracts the page title from a Notion page object
 * @param {Object} page - Notion page object
 * @returns {string} The page title or an empty string if not found
 */
function extractPageTitle(page) {
  if (!page || !page.properties) {
    return '';
  }

  // Try to find the title property
  // Notion pages typically have a "title" property or a property named "Title", "Name", etc.
  const titlePropertyNames = ['title', 'Title', 'Name', 'name'];
  
  // Look for a property with a title as the type
  for (const key in page.properties) {
    const property = page.properties[key];
    
    if (property.type === 'title' && property.title.length > 0) {
      return property.title.map(text => text.plain_text).join('');
    }
  }
  
  // If no title type found, look for properties with common title names
  for (const titleName of titlePropertyNames) {
    if (page.properties[titleName] && 
        page.properties[titleName].title && 
        page.properties[titleName].title.length > 0) {
      return page.properties[titleName].title.map(text => text.plain_text).join('');
    }
  }

  return '';
}

/**
 * Finds a page by its title in a specific database
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database to search
 * @param {string} title - Title to search for
 * @param {boolean} exactMatch - Whether to require an exact match (default: true)
 * @returns {Promise<Object|null>} The page object or null if not found
 */
async function findPageByTitle(notionClient, databaseId, title, exactMatch = true) {
  if (!notionClient || !databaseId || !title) {
    throw new Error('NotionClient, databaseId, and title are required');
  }

  // Create a filter for the database query based on whether we want exact matches
  const filter = exactMatch 
    ? {
        property: 'title',
        title: {
          equals: title
        }
      }
    : {
        property: 'title',
        title: {
          contains: title
        }
      };

  try {
    const response = await notionClient.queryDatabase(databaseId, filter);
    
    if (response.results && response.results.length > 0) {
      // If more than one result and exact match, prioritize exact matches
      if (response.results.length > 1 && exactMatch) {
        const exactMatches = response.results.filter(page => {
          const pageTitle = extractPageTitle(page);
          return pageTitle === title;
        });
        
        if (exactMatches.length > 0) {
          return exactMatches[0];
        }
      }
      
      return response.results[0];
    }
    
    return null;
  } catch (error) {
    throw new Error(`Error finding page by title: ${error.message}`);
  }
}

/**
 * Creates a unique title by adding incremental numbers if needed
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database to check against
 * @param {string} baseTitle - Original title to use as a base
 * @returns {Promise<string>} A unique title
 */
async function createUniqueTitle(notionClient, databaseId, baseTitle) {
  if (!notionClient || !databaseId || !baseTitle) {
    throw new Error('NotionClient, databaseId, and baseTitle are required');
  }

  // Try the base title first
  const basePageExists = await findPageByTitle(notionClient, databaseId, baseTitle);
  
  if (!basePageExists) {
    return baseTitle;
  }
  
  // Base title exists, try adding numbers
  let counter = 1;
  let uniqueTitle;
  let pageExists;
  
  do {
    uniqueTitle = `${baseTitle} ${counter}`;
    pageExists = await findPageByTitle(notionClient, databaseId, uniqueTitle);
    counter++;
  } while (pageExists);
  
  return uniqueTitle;
}

/**
 * Gets all pages from a database with optional filtering and sorting
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database
 * @param {Object} filter - Optional filter criteria
 * @param {Array} sorts - Optional sort criteria
 * @returns {Promise<Array>} Array of page objects
 */
async function getAllPagesFromDatabase(notionClient, databaseId, filter = {}, sorts = []) {
  if (!notionClient || !databaseId) {
    throw new Error('NotionClient and databaseId are required');
  }

  try {
    const response = await notionClient.queryDatabase(databaseId, filter, sorts);
    return response.results || [];
  } catch (error) {
    throw new Error(`Error getting pages from database: ${error.message}`);
  }
}

/**
 * Creates a title property object for a Notion page
 * @param {string} titleName - The name of the title property in the database schema
 * @param {string} titleValue - The value to set for the title
 * @returns {Object} A properly formatted title property object
 */
function createTitleProperty(titleName, titleValue) {
  return {
    [titleName]: {
      title: [
        {
          type: 'text',
          text: {
            content: titleValue
          }
        }
      ]
    }
  };
}

/**
 * Extracts all property values from a page into a simplified object
 * @param {Object} page - Notion page object
 * @returns {Object} Simple key-value object with property names and values
 */
function extractPageProperties(page) {
  if (!page || !page.properties) {
    return {};
  }

  const properties = {};
  
  for (const key in page.properties) {
    const property = page.properties[key];
    
    switch (property.type) {
      case 'title':
        properties[key] = property.title.map(text => text.plain_text).join('');
        break;
      
      case 'rich_text':
        properties[key] = property.rich_text.map(text => text.plain_text).join('');
        break;
      
      case 'select':
        properties[key] = property.select?.name || null;
        break;
      
      case 'multi_select':
        properties[key] = property.multi_select?.map(item => item.name) || [];
        break;
      
      case 'date':
        properties[key] = property.date;
        break;
      
      case 'checkbox':
        properties[key] = property.checkbox;
        break;
      
      case 'number':
        properties[key] = property.number;
        break;
      
      case 'url':
        properties[key] = property.url;
        break;
      
      case 'email':
        properties[key] = property.email;
        break;
      
      case 'phone_number':
        properties[key] = property.phone_number;
        break;
      
      case 'formula':
        properties[key] = property.formula.type === 'string' 
          ? property.formula.string 
          : property.formula.number;
        break;
      
      case 'relation':
        properties[key] = property.relation.map(item => item.id);
        break;
      
      case 'people':
        properties[key] = property.people.map(person => person.id);
        break;
      
      default:
        properties[key] = null;
    }
  }
  
  return properties;
}

module.exports = {
  extractPageTitle,
  findPageByTitle,
  createUniqueTitle,
  getAllPagesFromDatabase,
  createTitleProperty,
  extractPageProperties
};

/**
 * Core Notion API wrapper
 * Handles authentication and basic Notion API requests
 */

const { Client } = require('@notionhq/client');

/**
 * NotionClient class provides a wrapper around the Notion API
 * with methods for common operations and error handling
 */
class NotionClient {
  /**
   * Initialize a new Notion client
   * @param {string} apiKey - Notion API integration secret key
   */
  constructor(apiKey) {
    if (!apiKey) {
      throw new Error('Notion API key is required');
    }
    
    this.client = new Client({
      auth: apiKey,
    });
  }

  /**
   * Generic error handler for Notion API calls
   * @param {Error} error - Error object from Notion API
   * @param {string} operation - Description of the operation that failed
   * @throws {Error} Re-throws the error with additional context
   */
  handleError(error, operation) {
    // Extract status code if available
    const statusCode = error.status || error.code;
    
    // Handle specific error types
    if (statusCode === 401) {
      throw new Error(`Authentication error: Invalid Notion API key`);
    } else if (statusCode === 404) {
      throw new Error(`Not found: The requested Notion resource does not exist`);
    } else if (statusCode === 429) {
      throw new Error(`Rate limit exceeded: Too many requests to Notion API`);
    }
    
    // For all other errors, add context and re-throw
    throw new Error(`Notion API error during ${operation}: ${error.message}`);
  }

  /**
   * Retrieve a Notion page by ID
   * @param {string} pageId - ID of the Notion page
   * @returns {Promise<Object>} Page object from Notion API
   */
  async getPage(pageId) {
    try {
      return await this.client.pages.retrieve({ page_id: pageId });
    } catch (error) {
      this.handleError(error, `retrieving page ${pageId}`);
    }
  }

  /**
   * Retrieve a database by ID
   * @param {string} databaseId - ID of the Notion database
   * @returns {Promise<Object>} Database object from Notion API
   */
  async getDatabase(databaseId) {
    try {
      return await this.client.databases.retrieve({ database_id: databaseId });
    } catch (error) {
      this.handleError(error, `retrieving database ${databaseId}`);
    }
  }

  /**
   * Query a database for entries
   * @param {string} databaseId - ID of the Notion database
   * @param {Object} filter - Filter criteria for the query
   * @param {Array} sorts - Sort criteria for the query
   * @returns {Promise<Object>} Query results from Notion API
   */
  async queryDatabase(databaseId, filter = {}, sorts = []) {
    try {
      return await this.client.databases.query({
        database_id: databaseId,
        filter,
        sorts
      });
    } catch (error) {
      this.handleError(error, `querying database ${databaseId}`);
    }
  }

  /**
   * Retrieve all blocks for a page or block
   * @param {string} blockId - ID of the block or page to get children for
   * @returns {Promise<Array>} Array of block objects
   */
  async getBlockChildren(blockId) {
    try {
      const response = await this.client.blocks.children.list({
        block_id: blockId,
      });
      return response.results;
    } catch (error) {
      this.handleError(error, `retrieving children of block ${blockId}`);
    }
  }

  /**
   * Create a new page in a database
   * @param {string} databaseId - Parent database ID
   * @param {Object} properties - Page properties according to database schema
   * @param {Array} [children] - Optional array of block children
   * @returns {Promise<Object>} Created page object
   */
  async createPage(databaseId, properties, children = []) {
    try {
      return await this.client.pages.create({
        parent: { database_id: databaseId },
        properties,
        children
      });
    } catch (error) {
      this.handleError(error, `creating page in database ${databaseId}`);
    }
  }

  /**
   * Update a page's properties
   * @param {string} pageId - ID of the page to update
   * @param {Object} properties - Updated page properties
   * @returns {Promise<Object>} Updated page object
   */
  async updatePage(pageId, properties) {
    try {
      return await this.client.pages.update({
        page_id: pageId,
        properties
      });
    } catch (error) {
      this.handleError(error, `updating page ${pageId}`);
    }
  }

  /**
   * Create a new block as a child of an existing block
   * @param {string} blockId - Parent block ID
   * @param {Object} blockContent - Block content object
   * @returns {Promise<Object>} Created block object
   */
  async appendBlockChildren(blockId, blockContent) {
    try {
      return await this.client.blocks.children.append({
        block_id: blockId,
        children: Array.isArray(blockContent) ? blockContent : [blockContent]
      });
    } catch (error) {
      this.handleError(error, `appending block children to ${blockId}`);
    }
  }

  /**
   * Delete a block (sets to archived: true)
   * @param {string} blockId - ID of the block to delete
   * @returns {Promise<Object>} Deleted block object
   */
  async deleteBlock(blockId) {
    try {
      return await this.client.blocks.delete({
        block_id: blockId
      });
    } catch (error) {
      this.handleError(error, `deleting block ${blockId}`);
    }
  }
}

// Factory function to create a new NotionClient
function createNotionClient(apiKey) {
  return new NotionClient(apiKey);
}

module.exports = {
  createNotionClient,
  NotionClient
};

/**
 * Utility functions for creating and manipulating Notion blocks
 */

/**
 * Checks if content is already in Notion block format
 * @param {*} content - Content to check
 * @returns {boolean} True if content is in block format
 */
const isBlockFormat = (content) => {
    return Array.isArray(content) && 
           content.length > 0 && 
           content.every(item => typeof item === 'object' && item.type);
  };
  
  /**
   * Processes content into Notion blocks if not already in block format
   * @param {string|Array} content - Content to process
   * @returns {Array} Content in block format
   */
  const processIntoBlocks = (content) => {
    if (isBlockFormat(content)) {
      return content;
    }
    
    if (Array.isArray(content)) {
      return content.map(item => {
        if (typeof item === 'string') {
          return createParagraphBlock(item);
        }
        return item;
      });
    }
    
    if (typeof content === 'string') {
      // Split by double newlines to get paragraphs
      const paragraphs = content.split(/\n\n+/);
      return paragraphs
        .filter(p => p.trim().length > 0)
        .map(p => createParagraphBlock(p.trim()));
    }
    
    return [];
  };
  
  /**
   * Creates a rich text object
   * @param {string} content - Text content
   * @param {Object} annotations - Optional annotations for formatting
   * @returns {Object} Rich text object
   */
  const createRichText = (content, annotations = {}) => {
    return {
      type: 'text',
      text: { content },
      annotations: {
        bold: annotations.bold || false,
        italic: annotations.italic || false,
        strikethrough: annotations.strikethrough || false,
        underline: annotations.underline || false,
        code: annotations.code || false,
        color: annotations.color || 'default'
      }
    };
  };
  
  /**
   * Converts a string or array of strings to rich text array
   * @param {string|Array} text - Text content or array of rich text objects
   * @returns {Array} Array of rich text objects
   */
  const toRichTextArray = (text) => {
    if (!text) return [];
    
    if (Array.isArray(text)) {
      if (text.length === 0) return [];
      // If already rich text array format, return as is
      if (text[0].type && text[0].text) return text;
      // Convert array of strings to rich text objects
      return text.map(t => createRichText(String(t)));
    }
    
    return [createRichText(String(text))];
  };
  
  /**
   * Creates a paragraph block
   * @param {string|Array} text - Text content or rich text array
   * @returns {Object} Paragraph block
   */
  const createParagraphBlock = (text) => {
    return {
      type: 'paragraph',
      paragraph: {
        rich_text: toRichTextArray(text)
      }
    };
  };
  
  /**
   * Creates a heading block
   * @param {string|Array} text - Heading text or rich text array
   * @param {number} level - Heading level (1-3)
   * @returns {Object} Heading block
   */
  const createHeadingBlock = (text, level = 1) => {
    const validLevel = Math.min(Math.max(1, level), 3);
    const headingType = `heading_${validLevel}`;
    
    return {
      type: headingType,
      [headingType]: {
        rich_text: toRichTextArray(text)
      }
    };
  };
  
  /**
   * Creates a bulleted list item block
   * @param {string|Array} text - List item text or rich text array
   * @param {Array} children - Optional children blocks
   * @returns {Object} Bulleted list item block
   */
  const createBulletedListItemBlock = (text, children = []) => {
    const block = {
      type: 'bulleted_list_item',
      bulleted_list_item: {
        rich_text: toRichTextArray(text)
      }
    };
    
    if (children.length > 0) {
      block.bulleted_list_item.children = processIntoBlocks(children);
    }
    
    return block;
  };
  
  /**
   * Creates a numbered list item block
   * @param {string|Array} text - List item text or rich text array
   * @param {Array} children - Optional children blocks
   * @returns {Object} Numbered list item block
   */
  const createNumberedListItemBlock = (text, children = []) => {
    const block = {
      type: 'numbered_list_item',
      numbered_list_item: {
        rich_text: toRichTextArray(text)
      }
    };
    
    if (children.length > 0) {
      block.numbered_list_item.children = processIntoBlocks(children);
    }
    
    return block;
  };
  
  /**
   * Creates a to-do list item block
   * @param {string|Array} text - Task text or rich text array
   * @param {boolean} checked - Whether the task is checked
   * @param {Array} children - Optional children blocks
   * @returns {Object} To-do list item block
   */
  const createToDoBlock = (text, checked = false, children = []) => {
    const block = {
      type: 'to_do',
      to_do: {
        rich_text: toRichTextArray(text),
        checked
