/**
 * Enhanced markdown to Notion blocks converter with support for 
 * inline formatting and advanced markdown features
 * 
 * @param {string} markdown - The markdown text to convert
 * @returns {Array} - Array of Notion block objects
 */
function markdownToBlocks(markdown) {
  if (!markdown) return [];
  
  // First use the basic conversion from block-utils
  const basicBlocks = blockUtils.parseMarkdownToBlocks(markdown);
  
  // Then enhance blocks with inline formatting
  return enhanceBlocksWithInlineFormatting(basicBlocks);
}

/**
 * Enhanced Notion blocks to markdown converter with support for
 * inline formatting and advanced markdown features
 * 
 * @param {Array} blocks - Array of Notion block objects
 * @returns {string} - Markdown text
 */
function blocksToMarkdown(blocks) {
  if (!blocks || !blocks.length) return '';
  
  // Use the extended conversion that preserves more formatting
  return blocks.map(block => {
    const type = block.type;
    
    switch (type) {
      case 'paragraph':
        return parseRichText(block.paragraph?.rich_text);
        
      case 'heading_1':
        return `# ${parseRichText(block.heading_1?.rich_text)}`;
        
      case 'heading_2':
        return `## ${parseRichText(block.heading_2?.rich_text)}`;
        
      case 'heading_3':
        return `### ${parseRichText(block.heading_3?.rich_text)}`;
        
      case 'bulleted_list_item':
        return `- ${parseRichText(block.bulleted_list_item?.rich_text)}`;
        
      case 'numbered_list_item':
        return `1. ${parseRichText(block.numbered_list_item?.rich_text)}`;
        
      case 'to_do':
        const checked = block.to_do?.checked ? '[x]' : '[ ]';
        return `- ${checked} ${parseRichText(block.to_do?.rich_text)}`;
        
      case 'code':
        const language = block.code?.language || '';
        return '```' + language + '\n' + parseRichText(block.code?.rich_text) + '\n```';
        
      case 'quote':
        return `> ${parseRichText(block.quote?.rich_text)}`;
        
      case 'callout':
        const emoji = block.callout?.icon?.emoji || '💡';
        return `> ${emoji} ${parseRichText(block.callout?.rich_text)}`;
        
      case 'toggle':
        return `>>> ${parseRichText(block.toggle?.rich_text)}`;
        
      case 'divider':
        return '---';
        
      case 'image':
        const caption = block.image?.caption ? 
          block.image.caption.map(c => c.plain_text).join('') : '';
        const url = block.image?.type === 'external' ? 
          block.image.external.url : block.image.file.url;
        return `![${caption}](${url})`;
        
      default:
        // Fall back to block-utils for any unhandled types
        const singleBlockMarkdown = blockUtils.blocksToMarkdown([block]);
        return singleBlockMarkdown.trim();
    }
  }).filter(line => line).join('\n\n');
}

/**
 * Parses rich text content from a Notion block with formatting
 * @param {Array} richText - Notion rich text array
 * @returns {string} - Formatted text content
 */
function parseRichText(richText) {
  if (!richText || !Array.isArray(richText)) return '';
  
  return richText.map(textObj => {
    if (!textObj) return '';
    
    let text = textObj.text?.content || textObj.plain_text || '';
    
    // Apply formatting if annotations exist
    if (textObj.annotations) {
      if (textObj.annotations.bold) text = `**${text}**`;
      if (textObj.annotations.italic) text = `*${text}*`;
      if (textObj.annotations.strikethrough) text = `~~${text}~~`;
      if (textObj.annotations.code) text = `\`${text}\``;
      if (textObj.annotations.underline) text = `<u>${text}</u>`;
      
      // Handle color annotations
      if (textObj.annotations.color && textObj.annotations.color !== 'default') {
        text = `<span class="color-${textObj.annotations.color}">${text}</span>`;
      }
    }
    
    // Handle mention objects
    if (textObj.type === 'mention') {
      if (textObj.mention.type === 'user') {
        return `@${textObj.plain_text}`;
      } else if (textObj.mention.type === 'page') {
        return `[[${textObj.plain_text}]]`;
      } else if (textObj.mention.type === 'date') {
        const date = textObj.mention.date;
        return `@${date.start}${date.end ? ` -> ${date.end}` : ''}`;
      }
    }
    
    // Handle links
    if (textObj.href) {
      return `[${text}](${textObj.href})`;
    }
    
    return text;
  }).join('');
}

/**
 * Process markdown text to extract inline formatting
 * @param {string} text - Markdown text with inline formatting
 * @returns {Array} - Array of rich text objects with proper annotations
 */
function processInlineMarkdown(text) {
  if (!text) return [{ type: 'text', text: { content: '' } }];
  
  const richTextObjects = [];
  
  // Process bold text: **bold**
  let remaining = text;
  const boldRegex = /\*\*(.+?)\*\*/g;
  let boldMatch;
  const processed = new Set();
  
  while ((boldMatch = boldRegex.exec(text)) !== null) {
    const fullMatch = boldMatch[0];
    const innerContent = boldMatch[1];
    
    if (processed.has(fullMatch)) continue;
    processed.add(fullMatch);
    
    // Add text before the bold
    const indexBefore = remaining.indexOf(fullMatch);
    if (indexBefore > 0) {
      richTextObjects.push({
        type: 'text',
        text: { content: remaining.substring(0, indexBefore) }
      });
    }
    
    // Add the bold text
    richTextObjects.push({
      type: 'text',
      text: { content: innerContent },
      annotations: { bold: true }
    });
    
    // Update remaining text
    remaining = remaining.substring(indexBefore + fullMatch.length);
  }
  
  // Process italic text: *italic*
  const italicRegex = /(?<!\*)\*([^*]+)\*(?!\*)/g;
  let italicMatch;
  
  while ((italicMatch = italicRegex.exec(remaining)) !== null) {
    const fullMatch = italicMatch[0];
    const innerContent = italicMatch[1];
    
    if (processed.has(fullMatch)) continue;
    processed.add(fullMatch);
    
    // Add text before the italic
    const indexBefore = remaining.indexOf(fullMatch);
    if (indexBefore > 0) {
      richTextObjects.push({
        type: 'text',
        text: { content: remaining.substring(0, indexBefore) }
      });
    }
    
    // Add the italic text
    richTextObjects.push({
      type: 'text',
      text: { content: innerContent },
      annotations: { italic: true }
    });
    
    // Update remaining text
    remaining = remaining.substring(indexBefore + fullMatch.length);
  }
  
  // Process code: `code`
  const codeRegex = /`([^`]+)`/g;
  let codeMatch;
  
  while ((codeMatch = codeRegex.exec(remaining)) !== null) {
    const fullMatch = codeMatch[0];
    const innerContent = codeMatch[1];
    
    if (processed.has(fullMatch)) continue;
    processed.add(fullMatch);
    
    // Add text before the code
    const indexBefore = remaining.indexOf(fullMatch);
    if (indexBefore > 0) {
      richTextObjects.push({
        type: 'text',
        text: { content: remaining.substring(0, indexBefore) }
      });
    }
    
    // Add the code text
    richTextObjects.push({
      type: 'text',
      text: { content: innerContent },
      annotations: { code: true }
    });
    
    // Update remaining text
    remaining = remaining.substring(indexBefore + fullMatch.length);
  }
  
  // Process strikethrough: ~~text~~
  const strikeRegex = /~~(.+?)~~/g;
  let strikeMatch;
  
  while ((strikeMatch = strikeRegex.exec(remaining)) !== null) {
    const fullMatch = strikeMatch[0];
    const innerContent = strikeMatch[1];
    
    if (processed.has(fullMatch)) continue;
    processed.add(fullMatch);
    
    // Add text before the strikethrough
    const indexBefore = remaining.indexOf(fullMatch);
    if (indexBefore > 0) {
      richTextObjects.push({
        type: 'text',
        text: { content: remaining.substring(0, indexBefore) }
      });
    }
    
    // Add the strikethrough text
    richTextObjects.push({
      type: 'text',
      text: { content: innerContent },
      annotations: { strikethrough: true }
    });
    
    // Update remaining text
    remaining = remaining.substring(indexBefore + fullMatch.length);
  }
  
  // Add any remaining text
  if (remaining) {
    richTextObjects.push({
      type: 'text',
      text: { content: remaining }
    });
  }
  
  // If no formatting was found, return the original text
  if (richTextObjects.length === 0) {
    return [{ type: 'text', text: { content: text } }];
  }
  
