/**
 * page-routes.js
 * Express router for Notion page-related operations
 */

const express = require('express');
const router = express.Router();
const { createNotionClient } = require('./api');
const pageUtils = require('./page-utils');
const blockUtils = require('./block-utils');
const markdownUtils = require('./markdown-utils');

// Initialize Notion client
const notionClient = createNotionClient(process.env.NOTION_API_KEY);

/**
 * Error handler wrapper for async route handlers
 * @param {Function} fn - Async route handler function
 * @returns {Function} - Error-handled route handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates required parameters and returns an error message if missing
 * @param {Object} params - Parameters to validate
 * @returns {string|null} - Error message or null if valid
 */
const validateParams = (params) => {
  for (const [key, value] of Object.entries(params)) {
    if (!value) {
      return `Missing required parameter: ${key}`;
    }
  }
  return null;
};

// ROUTES

/**
 * Get a page by ID
 * GET /api/notion/pages/:pageId
 */
router.get('/:pageId', asyncHandler(async (req, res) => {
  const { pageId } = req.params;

  const errorMsg = validateParams({ pageId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  const page = await notionClient.getPage(pageId);

  // Extract page properties for a cleaner response
  const properties = pageUtils.extractPageProperties(page);

  res.json({
    id: page.id,
    url: page.url,
    created_time: page.created_time,
    last_edited_time: page.last_edited_time,
    properties
  });
}));

/**
 * Get page content (blocks)
 * GET /api/notion/pages/:pageId/content
 */
router.get('/:pageId/content', asyncHandler(async (req, res) => {
  const { pageId } = req.params;

  const errorMsg = validateParams({ pageId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  const blocks = await notionClient.getBlockChildren(pageId);
  res.json({ blocks });
}));

/**
 * Find a page by title in a database
 * GET /api/notion/pages/by-title/:databaseId
 * Query params:
 *  - title: Title to search for
 *  - exactMatch: Whether to require exact title match (default: true)
 */
router.get('/by-title/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { title, exactMatch = 'true' } = req.query;

  const errorMsg = validateParams({ databaseId, title });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  const isExactMatch = exactMatch.toLowerCase() === 'true';

  const page = await pageUtils.findPageByTitle(
    notionClient, 
    databaseId, 
    title, 
    isExactMatch
  );

  if (!page) {
    return res.status(404).json({ error: 'Page not found' });
  }

  // Extract page properties for a cleaner response
  const properties = pageUtils.extractPageProperties(page);

  res.json({
    id: page.id,
    url: page.url,
    created_time: page.created_time,
    last_edited_time: page.last_edited_time,
    properties
  });
}));

/**
 * Get all pages from a database
 * GET /api/notion/pages/database/:databaseId
 * Query params:
 *  - filter: JSON string of filter criteria
 *  - sorts: JSON string of sort criteria
 */
router.get('/database/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { filter, sorts } = req.query;

  const errorMsg = validateParams({ databaseId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  let filterObj = {};
  let sortsArray = [];

  try {
    if (filter) {
      filterObj = JSON.parse(filter);
    }

    if (sorts) {
      sortsArray = JSON.parse(sorts);
    }
  } catch (error) {
    return res.status(400).json({ error: 'Invalid filter or sorts JSON format' });
  }

  const pages = await pageUtils.getAllPagesFromDatabase(
    notionClient, 
    databaseId, 
    filterObj, 
    sortsArray
  );

  // Extract page properties for cleaner responses
  const simplifiedPages = pages.map(page => ({
    id: page.id,
    url: page.url,
    created_time: page.created_time,
    last_edited_time: page.last_edited_time,
    properties: pageUtils.extractPageProperties(page)
  }));

  res.json({ pages: simplifiedPages });
}));

/**
 * Create a new page in a database
 * POST /api/notion/pages/database/:databaseId
 * Body:
 *  - title: Title of the page
 *  - titleProperty: Name of the title property in the database schema (default: 'title')
 *  - properties: Other properties for the page (optional)
 *  - content: Content blocks or markdown (optional)
 *  - contentFormat: 'blocks' or 'markdown' (default: 'blocks')
 *  - preventDuplicates: Whether to ensure title is unique (default: true)
 */
router.post('/database/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { 
    title, 
    titleProperty = 'title', 
    properties = {}, 
    content,
    contentFormat = 'blocks',
    preventDuplicates = true
  } = req.body;

  const errorMsg = validateParams({ databaseId, title });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  let finalTitle = title;

  // If preventing duplicates, get a unique title
  if (preventDuplicates === true) {
    try {
      finalTitle = await pageUtils.createUniqueTitle(notionClient, databaseId, title);
    } catch (error) {
      return res.status(400).json({ error: error.message });
    }
  }

  // Create properties object with title
  const titleProp = pageUtils.createTitleProperty(titleProperty, finalTitle);
  const allProperties = { ...titleProp, ...properties };

  // Prepare content blocks if provided
  let contentBlocks = [];
  if (content) {
    if (contentFormat === 'markdown') {
      // Convert markdown to blocks
      contentBlocks = markdownUtils.batchMarkdownToBlocks(content);
    } else {
      // Use blocks directly
      contentBlocks = Array.isArray(content) ? content : [content];
    }
  }

  // Create the page
  const newPage = await notionClient.createPage(databaseId, allProperties, contentBlocks);

  res.status(201).json({
    id: newPage.id,
    url: newPage.url,
    title: finalTitle,
    created_time: newPage.created_time,
    properties: pageUtils.extractPageProperties(newPage)
  });
}));

/**
 * Update a page by ID
 * PATCH /api/notion/pages/:pageId
 * Body:
 *  - properties: Page properties to update
 */
router.patch('/:pageId', asyncHandler(async (req, res) => {
  const { pageId } = req.params;
  const { properties } = req.body;

  const errorMsg = validateParams({ pageId, properties });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  const updatedPage = await notionClient.updatePage(pageId, properties);

  res.json({
    id: updatedPage.id,
    url: updatedPage.url,
    last_edited_time: updatedPage.last_edited_time,
    properties: pageUtils.extractPageProperties(updatedPage)
  });
}));

/**
 * Update a page by title
 * PATCH /api/notion/pages/by-title/:databaseId
 * Query params:
 *  - title: Title to search for
 * Body:
 *  - properties: Page properties to update
 */
router.patch('/by-title/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { title } = req.query;
  const { properties } = req.body;

  const errorMsg = validateParams({ databaseId, title, properties });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // Find the page by title
  const page = await pageUtils.findPageByTitle(notionClient, databaseId, title, true);

  if (!page) {
    return res.status(404).json({ error: 'Page not found' });
  }

  // Update the page
  const updatedPage = await notionClient.updatePage(page.id, properties);

  res.json({
    id: updatedPage.id,
    url: updatedPage.url,
    last_edited_time: updatedPage.last_edited_time,
    properties: pageUtils.extractPageProperties(updatedPage)
  });
}));

/**
 * Add content to a page
 * POST /api/notion/pages/:pageId/content
 * Body:
 *  - content: Content blocks or markdown
 *  - format: 'blocks' or 'markdown' (default: 'blocks')
 */
router.post('/:pageId/content', asyncHandler(async (req, res) => {
  const { pageId } = req.params;
  const { content, format = 'blocks' } = req.body;

  const errorMsg = validateParams({ pageId, content });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // Prepare content blocks
  let contentBlocks;
  if (format === 'markdown') {
    // Convert markdown to blocks
    contentBlocks = markdownUtils.batchMarkdownToBlocks(content);
  } else {
    // Use blocks directly
    contentBlocks = Array.isArray(content) ? content : [content];
  }

  // Add content to the page
  const result = await notionClient.appendBlockChildren(pageId, contentBlocks);

  res.json({
    success: true,
    added_blocks: result.results
  });
}));

/**
 * Delete a page (archive it)
 * DELETE /api/notion/pages/:pageId
 */
router.delete('/:pageId', asyncHandler(async (req, res) => {
  const { pageId } = req.params;

  const errorMsg = validateParams({ pageId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // In Notion, "deleting" a page is actually archiving it by updating its archived property
  const archivedPage = await notionClient.updatePage(pageId, { archived: true });

  res.json({
    success: true,
    id: archivedPage.id,
    archived: true
  });
}));

/**
 * Delete a page by title (archive it)
 * DELETE /api/notion/pages/by-title/:databaseId
 * Query params:
 *  - title: Title to search for
 */
router.delete('/by-title/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { title } = req.query;

  const errorMsg = validateParams({ databaseId, title });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // Find the page by title
  const page = await pageUtils.findPageByTitle(notionClient, databaseId, title, true);

  if (!page) {
    return res.status(404).json({ error: 'Page not found' });
  }

  // Archive the page
  const archivedPage = await notionClient.updatePage(page.id, { archived: true });

  res.json({
    success: true,
    id: archivedPage.id,
    title: title,
    archived: true
  });
}));

/**
 * Convert blocks to markdown
 * POST /api/notion/pages/convert/blocks-to-markdown
 * Body:
 *  - blocks: Array of Notion blocks
 */
router.post('/convert/blocks-to-markdown', asyncHandler(async (req, res) => {
  const { blocks } = req.body;

  const errorMsg = validateParams({ blocks });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  try {
    const markdown = markdownUtils.batchBlocksToMarkdown(blocks);
    res.json({ markdown });
  } catch (error) {
    res.status(400).json({ error: 'Failed to convert blocks to markdown: ' + error.message });
  }
}));

/**
 * Convert markdown to blocks
 * POST /api/notion/pages/convert/markdown-to-blocks
 * Body:
 *  - markdown: Markdown text
 */
router.post('/convert/markdown-to-blocks', asyncHandler(async (req, res) => {
  const { markdown } = req.body;

  const errorMsg = validateParams({ markdown });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  try {
    const blocks = markdownUtils.batchMarkdownToBlocks(markdown);
    res.json({ blocks });
  } catch (error) {
    res.status(400).json({ error: 'Failed to convert markdown to blocks: ' + error.message });
  }
}));

/**
 * Get page content as markdown
 * GET /api/notion/pages/:pageId/markdown
 */
router.get('/:pageId/markdown', asyncHandler(async (req, res) => {
  const { pageId } = req.params;

  const errorMsg = validateParams({ pageId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }

  // Get the page blocks
  const blocks = await notionClient.getBlockChildren(pageId);

  // Convert to markdown
  const markdown = markdownUtils.batchBlocksToMarkdown(blocks);

  res.json({ markdown });
}));

module.exports = router;

/**
 * markdown-utils.js
 * Utilities for converting between markdown and Notion blocks
 */

/**
 * Converts markdown text to Notion blocks
 * @param {string} markdown - The markdown text to convert
 * @returns {Array} - Array of Notion block objects
 */
function markdownToBlocks(markdown) {
  if (!markdown) return [];

  const lines = markdown.split('\n');
  const blocks = [];
  let codeBlockLines = [];
  let inCodeBlock = false;
  let codeLanguage = '';

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    // Handle code blocks
    if (line.startsWith('```')) {
      if (!inCodeBlock) {
        inCodeBlock = true;
        codeLanguage = line.slice(3).trim();
        codeBlockLines = [];
      } else {
        blocks.push({
          type: 'code',
          code: {
            rich_text: [{
              type: 'text',
              text: { content: codeBlockLines.join('\n') }
            }],
            language: codeLanguage || 'plain_text'
          }
        });
        inCodeBlock = false;
      }
      continue;
    }

    if (inCodeBlock) {
      codeBlockLines.push(line);
      continue;
    }

    // Skip empty lines
    if (!line.trim()) {
      blocks.push({ type: 'paragraph', paragraph: { rich_text: [] } });
      continue;
    }

    // Handle headings
    if (line.startsWith('# ')) {
      blocks.push({
        type: 'heading_1',
        heading_1: {
          rich_text: [{ type: 'text', text: { content: line.slice(2) } }]
        }
      });
    } else if (line.startsWith('## ')) {
      blocks.push({
        type: 'heading_2',
        heading_2: {
          rich_text: [{ type: 'text', text: { content: line.slice(3) } }]
        }
      });
    } else if (line.startsWith('### ')) {
      blocks.push({
        type: 'heading_3',
        heading_3: {
          rich_text: [{ type: 'text', text: { content: line.slice(4) } }]
        }
      });
    }
    // Handle bullet lists
    else if (line.startsWith('- ') || line.startsWith('* ')) {
      blocks.push({
        type: 'bulleted_list_item',
        bulleted_list_item: {
          rich_text: [{ type: 'text', text: { content: line.slice(2) } }]
        }
      });
    }
    // Handle numbered lists
    else if (/^\d+\.\s/.test(line)) {
      const content = line.replace(/^\d+\.\s/, '');
      blocks.push({
        type: 'numbered_list_item',
        numbered_list_item: {
          rich_text: [{ type: 'text', text: { content } }]
        }
      });
    }
    // Handle blockquotes
    else if (line.startsWith('> ')) {
      blocks.push({
        type: 'quote',
        quote: {
          rich_text: [{ type: 'text', text: { content: line.slice(2) } }]
        }
      });
    }
    // Handle horizontal rule
    else if (line === '---' || line === '***' || line === '___') {
      blocks.push({ type: 'divider', divider: {} });
    }
    // Default to paragraph
    else {
      blocks.push({
        type: 'paragraph',
        paragraph: {
          rich_text: [{ type: 'text', text: { content: line } }]
        }
      });
    }
  }

  return blocks;
}

/**
 * Parses rich text content from a Notion block
 * @param {Array} richText - Notion rich text array
 * @returns {string} - Plain text content
 */
function parseRichText(richText) {
  if (!richText || !richText.length) return '';

  return richText.map(textObj => {
    let text = textObj.text.content;

    // Apply formatting
    if (textObj.annotations) {
      if (textObj.annotations.bold) text = `**${text}**`;
      if (textObj.annotations.italic) text = `*${text}*`;
      if (textObj.annotations.strikethrough) text = `~~${text}~~`;
      if (textObj.annotations.code) text = `\`${text}\``;
    }

    return text;
  }).join('');
}

/**
 * Converts Notion blocks to markdown text
 * @param {Array} blocks - Array of Notion block objects
 * @returns {string} - Markdown text
 */
function blocksToMarkdown(blocks) {
  if (!blocks || !blocks.length) return '';

  return blocks.map(block => {
    switch (block.type) {
      case 'paragraph':
        return parseRichText(block.paragraph.rich_text);

      case 'heading_1':
        return `# ${parseRichText(block.heading_1.rich_text)}`;

      case 'heading_2':
        return `## ${parseRichText(block.heading_2.rich_text)}`;

      case 'heading_3':
        return `### ${parseRichText(block.heading_3.rich_text)}`;

      case 'bulleted_list_item':
        return `- ${parseRichText(block.bulleted_list_item.rich_text)}`;

      case 'numbered_list_item':
        return `1. ${parseRichText(block.numbered_list_item.rich_text)}`;

      case 'to_do':
        const checked = block.to_do.checked ? '[x]' : '[ ]';
        return `- ${checked} ${parseRichText(block.to_do.rich_text)}`;

      case 'code':
        const language = block.code.language || '';
        return '```' + language + '\n' + parseRichText(block.code.rich_text) + '\n```';

      case 'quote':
        return `> ${parseRichText(block.quote.rich_text)}`;

      case 'divider':
        return '---';

      case 'image':
        const caption = block.image.caption ? block.image.caption.map(c => c.plain_text).join('') : '';
        const url = block.image.type === 'external' ? block.image.external.url : block.image.file.url;
        return `![${caption}](${url})`;

      default:
        return '';
    }
  }).filter(line => line).join('\n\n');
}

/**
 * Processes inline markdown formatting within text
 * @param {string} text - Text with markdown formatting
 * @returns {Array} - Array of rich text objects with annotations
 */
function processInlineMarkdown(text) {
  if (!text) return [];

  const richTextObjects = [];
  let currentText = text;

  // Process bold text (**text**)
  const boldRegex = /\*\*(.*?)\*\*/g;
  let boldMatch;
  while ((boldMatch = boldRegex.exec(text)) !== null) {
    richTextObjects.push({
      type: 'text',
      text: { content: boldMatch[1] },
      annotations: { bold: true }
    });
    currentText = currentText.replace(boldMatch[0], '');
  }

  // Process italic text (*text*)
  const italicRegex = /\*(.*?)\*/g;
  let italicMatch;
  while ((italicMatch = italicRegex.exec(currentText)) !== null) {
    richTextObjects.push({
      type: 'text',
      text: { content: italicMatch[1] },
      annotations: { italic: true }
    });
    currentText = currentText.replace(italicMatch[0], '');
  }

  // Process code (`text`)
  const codeRegex = /`(.*?)`/g;
  let codeMatch;
  while ((codeMatch = codeRegex.exec(currentText)) !== null) {
    richTextObjects.push({
      type: 'text',
      text: { content: codeMatch[1] },
      annotations: { code: true }
    });
    currentText = currentText.replace(codeMatch[0], '');
  }

  // Add any remaining text
  if (currentText.trim()) {
    richTextObjects.push({
      type: 'text',
      text: { content: currentText.trim() }
    });
  }

  return richTextObjects.length ? richTextObjects : [{ type: 'text', text: { content: text } }];
}

/**
 * Enhances a Notion block by processing inline markdown within rich_text
 * @param {Object} block - Notion block object
 * @returns {Object} - Enhanced block with proper rich text annotations
 */
function enhanceBlockWithInlineMarkdown(block) {
  if (!block) return block;

  const enhancedBlock = { ...block };

  Object.keys(enhancedBlock).forEach(key => {
    if (key === 'rich_text' && Array.isArray(enhancedBlock[key])) {
      enhancedBlock[key] = enhancedBlock[key].flatMap(textObj => {
        if (textObj.type === 'text') {
          return processInlineMarkdown(textObj.text.content);
        }
        return textObj;
      });
    } else if (typeof enhancedBlock[key] === 'object' && enhancedBlock[key] !== null) {
      enhancedBlock[key] = enhanceBlockWithInlineMarkdown(enhancedBlock[key]);
    }
  });

  return enhancedBlock;
}

module.exports = {
  markdownToBlocks,
  blocksToMarkdown,
  parseRichText,
  processInlineMarkdown,
  enhanceBlockWithInlineMarkdown
};

