    const indexBefore = remaining.indexOf(fullMatch);
    if (indexBefore > 0) {
      richTextObjects.push({
        type: 'text',
        text: { content: remaining.substring(0, indexBefore) }
      });
    }
    
    // Add the italic text
    richTextObjects.push({
      type: 'text',
      text: { content: innerContent },
      annotations: { italic: true }
    });
    
    // Update remaining text
    remaining = remaining.substring(indexBefore + fullMatch.length);
  }
  
  // Process code: `code`
  const codeRegex = /`([^`]+)`/g;
  let codeMatch;
  
  while ((codeMatch = codeRegex.exec(remaining)) !== null) {
    const fullMatch = codeMatch[0];
    const innerContent = codeMatch[1];
    
    if (processed.has(fullMatch)) continue;
    processed.add(fullMatch);
    
    // Add text before the code
    const indexBefore = remaining.indexOf(fullMatch);
