    },
    "dependencies": {
      "@notionhq/client": "^2.2.14",
      "dotenv": "^16.3.1",
      "express": "^4.18.2"
    },
    "devDependencies": {
      "nodemon": "^3.0.2"
    },
    "engines": {
      "node": ">=16.0.0"
    }
  }

/**
 * Core Notion API wrapper
 * Handles authentication and basic Notion API requests
 */

const { Client } = require('@notionhq/client');

/**
 * NotionClient class provides a wrapper around the Notion API
 * with methods for common operations and error handling
 */
class NotionClient {
  /**
   * Initialize a new Notion client
   * @param {string} apiKey - Notion API integration secret key
   */
  constructor(apiKey) {
    if (!apiKey) {
      throw new Error('Notion API key is required');
    }
    
    this.client = new Client({
      auth: apiKey,
    });
  }

  /**
   * Generic error handler for Notion API calls
   * @param {Error} error - Error object from Notion API
   * @param {string} operation - Description of the operation that failed
   * @throws {Error} Re-throws the error with additional context
   */
  handleError(error, operation) {
    // Extract status code if available
    const statusCode = error.status || error.code;
    
    // Handle specific error types
    if (statusCode === 401) {
      throw new Error(`Authentication error: Invalid Notion API key`);
    } else if (statusCode === 404) {
      throw new Error(`Not found: The requested Notion resource does not exist`);
    } else if (statusCode === 429) {
      throw new Error(`Rate limit exceeded: Too many requests to Notion API`);
    }
    
    // For all other errors, add context and re-throw
    throw new Error(`Notion API error during ${operation}: ${error.message}`);
  }

  /**
   * Retrieve a Notion page by ID
   * @param {string} pageId - ID of the Notion page
   * @returns {Promise<Object>} Page object from Notion API
   */
  async getPage(pageId) {
    try {
      return await this.client.pages.retrieve({ page_id: pageId });
    } catch (error) {
      this.handleError(error, `retrieving page ${pageId}`);
    }
  }

  /**
   * Retrieve a database by ID
   * @param {string} databaseId - ID of the Notion database
   * @returns {Promise<Object>} Database object from Notion API
   */
  async getDatabase(databaseId) {
    try {
      return await this.client.databases.retrieve({ database_id: databaseId });
    } catch (error) {
      this.handleError(error, `retrieving database ${databaseId}`);
    }
  }

  /**
   * Query a database for entries
   * @param {string} databaseId - ID of the Notion database
   * @param {Object} filter - Filter criteria for the query
   * @param {Array} sorts - Sort criteria for the query
   * @returns {Promise<Object>} Query results from Notion API
   */
  async queryDatabase(databaseId, filter = {}, sorts = []) {
    try {
      return await this.client.databases.query({
        database_id: databaseId,
        filter,
        sorts
      });
    } catch (error) {
      this.handleError(error, `querying database ${databaseId}`);
    }
  }

  /**
   * Retrieve all blocks for a page or block
   * @param {string} blockId - ID of the block or page to get children for
   * @returns {Promise<Array>} Array of block objects
   */
  async getBlockChildren(blockId) {
    try {
      const response = await this.client.blocks.children.list({
        block_id: blockId,
      });
      return response.results;
    } catch (error) {
      this.handleError(error, `retrieving children of block ${blockId}`);
    }
  }

  /**
   * Create a new page in a database
   * @param {string} databaseId - Parent database ID
   * @param {Object} properties - Page properties according to database schema
   * @param {Array} [children] - Optional array of block children
   * @returns {Promise<Object>} Created page object
   */
  async createPage(databaseId, properties, children = []) {
    try {
      return await this.client.pages.create({
        parent: { database_id: databaseId },
        properties,
        children
      });
    } catch (error) {
      this.handleError(error, `creating page in database ${databaseId}`);
    }
  }

  /**
   * Update a page's properties
   * @param {string} pageId - ID of the page to update
   * @param {Object} properties - Updated page properties
   * @returns {Promise<Object>} Updated page object
   */
  async updatePage(pageId, properties) {
    try {
      return await this.client.pages.update({
        page_id: pageId,
        properties
      });
    } catch (error) {
      this.handleError(error, `updating page ${pageId}`);
    }
  }

  /**
   * Create a new block as a child of an existing block
   * @param {string} blockId - Parent block ID
   * @param {Object} blockContent - Block content object
   * @returns {Promise<Object>} Created block object
   */
  async appendBlockChildren(blockId, blockContent) {
    try {
      return await this.client.blocks.children.append({
        block_id: blockId,
        children: Array.isArray(blockContent) ? blockContent : [blockContent]
      });
    } catch (error) {
      this.handleError(error, `appending block children to ${blockId}`);
    }
  }

