    const statusCode = error.status || error.code;
    
    // Handle specific error types
    if (statusCode === 401) {
      throw new Error(`Authentication error: Invalid Notion API key`);
    } else if (statusCode === 404) {
      throw new Error(`Not found: The requested Notion resource does not exist`);
    } else if (statusCode === 429) {
      throw new Error(`Rate limit exceeded: Too many requests to Notion API`);
