/**
 * Parses markdown links in text and converts to Notion link format
 * @param {string} text - Text that may contain markdown links
 * @returns {Array} - Array of rich text objects with links
 */
function parseMarkdownLinks(text) {
  if (!text) return [{ type: 'text', text: { content: '' } }];
  
  const linkRegex = /\[([^\]]+)\]\(([^)]+)\)/g;
  let match;
  let lastIndex = 0;
  const richTextObjects = [];
  
  while ((match = linkRegex.exec(text)) !== null) {
    const [fullMatch, linkText, url] = match;
    
    // Add text before the link
    if (match.index > lastIndex) {
      richTextObjects.push({
        type: 'text',
        text: { content: text.substring(lastIndex, match.index) }
      });
    }
    
    // Add the link
    richTextObjects.push({
      type: 'text',
      text: { content: linkText },
      href: url
    });
    
    lastIndex = match.index + fullMatch.length;
  }
  
  // Add any remaining text
  if (lastIndex < text.length) {
    richTextObjects.push({
      type: 'text',
      text: { content: text.substring(lastIndex) }
    });
  }
  
  // If no links were found, return the original text
  if (richTextObjects.length === 0) {
    return [{ type: 'text', text: { content: text } }];
  }
  
  return richTextObjects;
}

/**
 * Converts a markdown table to a Notion table block
 * @param {string} markdownTable - The markdown table text
 * @returns {Object} - Notion table block
 */
function markdownTableToNotionTable(markdownTable) {
  if (!markdownTable) return null;
  
  const lines = markdownTable.split('\n').filter(line => line.trim());
  if (lines.length < 2) return null; // Need at least header and separator
  
  const headerRow = lines[0];
  const separatorRow = lines[1];
  
  // Validate it's a markdown table by checking separator row format
  if (!separatorRow.includes('|') || !separatorRow.includes('-')) {
    return null;
  }
  
  // Parse header cells
  const headerCells = headerRow
    .split('|')
    .map(cell => cell.trim())
    .filter(cell => cell);
    
  // Create table rows for data
  const tableRows = [];
  
  // Process header row
  tableRows.push({
    cells: headerCells.map(cell => [{
      type: 'text',
      text: { content: cell }
    }])
  });
  
  // Process data rows (skip separator row)
  for (let i = 2; i < lines.length; i++) {
    const rowCells = lines[i]
      .split('|')
      .map(cell => cell.trim())
      .filter(cell => cell);
      
    tableRows.push({
      cells: rowCells.map(cell => [{
        type: 'text',
        text: { content: cell }
      }])
    });
  }
  
  return {
    object: 'block',
    type: 'table',
    table: {
      table_width: headerCells.length,
      has_column_header: true,
      has_row_header: false,
      rows: tableRows
    }
  };
}

/**
 * Converts a Notion table block to markdown table
 * @param {Object} tableBlock - Notion table block
 * @returns {string} - Markdown table
 */
function notionTableToMarkdown(tableBlock) {
  if (!tableBlock || tableBlock.type !== 'table' || !tableBlock.table) {
    return '';
  }
  
  const { rows } = tableBlock.table;
  if (!rows || !rows.length) return '';
  
  const tableWidth = tableBlock.table.table_width || rows[0].cells.length;
  let markdownTable = '';
  
  // Process all rows
  rows.forEach((row, rowIndex) => {
    let rowText = '|';
    
    // Process each cell in the row
    for (let i = 0; i < tableWidth; i++) {
      const cell = row.cells[i] || [];
      const cellText = cell.map(rt => parseRichText([rt])).join('');
      rowText += ` ${cellText} |`;
    }
    
    markdownTable += rowText + '\n';
    
    // Add separator row after header
    if (rowIndex === 0 && tableBlock.table.has_column_header) {
      markdownTable += '|' + ' --- |'.repeat(tableWidth) + '\n';
    }
  });
  
  return markdownTable;
}

/**
 * Batch converts multiple Notion blocks to markdown
 * @param {Array} blocks - Array of Notion blocks
 * @returns {string} - Markdown text
 */
function batchBlocksToMarkdown(blocks) {
  return blocksToMarkdown(blocks);
}

/**
 * Batch converts markdown text to multiple Notion blocks
 * @param {string} markdown - Markdown text
 * @returns {Array} - Array of Notion blocks
 */
function batchMarkdownToBlocks(markdown) {
  return markdownToBlocks(markdown);
}

module.exports = {
  // Main conversion functions
  markdownToBlocks,
  blocksToMarkdown,
  
  // Batch conversion helpers
  batchMarkdownToBlocks,
  batchBlocksToMarkdown,
  
  // Specialized helpers
  parseRichText,
  processInlineMarkdown,
  enhanceBlocksWithInlineFormatting,
  parseMarkdownLinks,
  markdownTableToNotionTable,
  notionTableToMarkdown
};

