/**
 * Notion routes entry point
 * Combines all Notion-related routes
 */
const express = require('express');
const router = express.Router();
const { createNotionClient } = require('./api');

// Initialize Notion client
const notionClient = createNotionClient(process.env.NOTION_API_KEY);

// Basic health check route
router.get('/health', (req, res) => {
  res.json({ status: 'Notion API connection ready' });
});

// Simple test route to verify Notion API connection
router.get('/test', async (req, res, next) => {
