    // Try to search for a user to verify API connectivity
    // This is a lightweight operation that doesn't require specific permissions
    await notionClient.client.users.list();
    res.json({ status: 'connected', message: 'Successfully connected to Notion API' });
  } catch (error) {
    next(error);
  }
});

// Note: Additional route handlers will be imported and registered in future implementations
 const pageRoutes = require('./page-routes');
 const memoryDbRoutes = require('./memory-db-routes');

 router.use('/pages', pageRoutes);
 router.use('/memory-db', memoryDbRoutes);

module.exports = router;

/**
 * memory-db-routes.js
 * Express router for Notion memory entries and database operations
 */

const express = require('express');
const router = express.Router();
const { createNotionClient } = require('./api');

// Initialize Notion client
const notionClient = createNotionClient(process.env.NOTION_API_KEY);

/**
 * Error handler wrapper for async route handlers
 * @param {Function} fn - Async route handler function
 * @returns {Function} - Error-handled route handler
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Validates required parameters and returns an error message if missing
 * @param {Object} params - Parameters to validate
 * @returns {string|null} - Error message or null if valid
 */
const validateParams = (params) => {
  for (const [key, value] of Object.entries(params)) {
    if (!value) {
      return `Missing required parameter: ${key}`;
    }
  }
  return null;
};

// ============================================================================
// MEMORY ROUTES
// ============================================================================

/**
 * Create a memory entry in a database
 * POST /api/notion/memory-db/memory/:databaseId
 * Body:
 *  - title: Title of the memory entry
 *  - content: Content of the memory entry
 *  - tags: Array of tags (optional)
 *  - properties: Other properties for the entry (optional)
 */
router.post('/memory/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { title, content, tags = [], properties = {} } = req.body;
  
  const errorMsg = validateParams({ databaseId, title, content });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Prepare properties object
  const memoryProperties = {
    title: {
      title: [
        {
          type: 'text',
          text: {
            content: title
          }
        }
      ]
    },
    ...properties
  };
  
  // Add tags if provided
  if (tags.length > 0) {
    memoryProperties.tags = {
      multi_select: tags.map(tag => ({ name: tag }))
    };
  }
  
  // Create content block
  const contentBlock = {
    type: 'paragraph',
    paragraph: {
      rich_text: [
        {
          type: 'text',
          text: {
            content
          }
        }
      ]
    }
  };
  
  // Create the memory entry
  const newMemory = await notionClient.createPage(databaseId, memoryProperties, [contentBlock]);
  
  res.status(201).json({
    success: true,
    message: 'Memory entry created successfully',
    id: newMemory.id,
    url: newMemory.url
  });
}));

/**
 * Get a memory entry by ID
 * GET /api/notion/memory-db/memory/:memoryId
 */
router.get('/memory/:memoryId', asyncHandler(async (req, res) => {
  const { memoryId } = req.params;
  
  const errorMsg = validateParams({ memoryId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Get the memory page
  const memory = await notionClient.getPage(memoryId);
  
  // Get the memory content
  const blocks = await notionClient.getBlockChildren(memoryId);
  
  // Extract properties
  const properties = {};
  for (const key in memory.properties) {
    const prop = memory.properties[key];
    if (prop.type === 'title') {
      properties.title = prop.title.map(t => t.plain_text).join('');
    } else if (prop.type === 'multi_select') {
      properties[key] = prop.multi_select.map(item => item.name);
    } else if (prop.type === 'rich_text') {
      properties[key] = prop.rich_text.map(t => t.plain_text).join('');
    } else if (prop.type === 'date') {
      properties[key] = prop.date;
    } else if (prop.type === 'checkbox') {
      properties[key] = prop.checkbox;
    } else {
      properties[key] = prop;
    }
  }
  
  res.json({
    id: memory.id,
    created_time: memory.created_time,
    last_edited_time: memory.last_edited_time,
    properties,
    content: blocks
  });
}));

/**
 * List all memory entries in a database
 * GET /api/notion/memory-db/memory/list/:databaseId
 * Query params:
 *  - limit: Number of entries to return (default: 10)
 *  - tag: Filter by tag (optional)
 *  - search: Search term (optional)
 */
router.get('/memory/list/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  const { limit = 10, tag, search } = req.query;
  
  const errorMsg = validateParams({ databaseId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Build filter object
  let filter = {};
  
  if (tag) {
    filter = {
      property: 'tags',
      multi_select: {
        contains: tag
      }
    };
  }
  
  if (search) {
    filter = {
      property: 'title',
      title: {
        contains: search
      }
    };
  }
  
  // If both tag and search are provided, use an AND filter
  if (tag && search) {
    filter = {
      and: [
        {
          property: 'tags',
          multi_select: {
            contains: tag
          }
        },
        {
          property: 'title',
          title: {
            contains: search
          }
        }
      ]
    };
  }
  
  // Query the database with filter
  const response = await notionClient.queryDatabase(databaseId, filter);
  
  // Extract limited number of entries
  const entries = response.results
    .slice(0, parseInt(limit, 10))
    .map(page => {
      // Extract title
      const title = page.properties.title?.title
        ?.map(t => t.plain_text)
        .join('') || 'Untitled';
      
      // Extract tags
      const tags = page.properties.tags?.multi_select
        ?.map(item => item.name) || [];
      
      return {
        id: page.id,
        title,
        tags,
        created_time: page.created_time,
        last_edited_time: page.last_edited_time,
        url: page.url
      };
    });
  
  res.json({
    entries,
    has_more: response.has_more
  });
}));

/**
 * Update a memory entry
 * PATCH /api/notion/memory-db/memory/:memoryId
 * Body:
 *  - title: New title (optional)
 *  - content: New content (optional)
 *  - tags: New tags array (optional)
 *  - properties: Other properties to update (optional)
 */
router.patch('/memory/:memoryId', asyncHandler(async (req, res) => {
  const { memoryId } = req.params;
  const { title, content, tags, properties = {} } = req.body;
  
  const errorMsg = validateParams({ memoryId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Prepare properties to update
  const updatedProperties = { ...properties };
  
  // Update title if provided
  if (title) {
    updatedProperties.title = {
      title: [
        {
          type: 'text',
          text: {
            content: title
          }
        }
      ]
    };
  }
  
  // Update tags if provided
  if (tags) {
    updatedProperties.tags = {
      multi_select: tags.map(tag => ({ name: tag }))
    };
  }
  
  // Update properties
  await notionClient.updatePage(memoryId, updatedProperties);
  
  // Update content if provided
  if (content) {
    // First get existing blocks to update the first paragraph
    const blocks = await notionClient.getBlockChildren(memoryId);
    
    // Find the first paragraph block or create new one
    const paragraphBlockId = blocks.find(b => b.type === 'paragraph')?.id;
    
    if (paragraphBlockId) {
      // Update existing paragraph
      await notionClient.client.blocks.update({
        block_id: paragraphBlockId,
        paragraph: {
          rich_text: [
            {
              type: 'text',
              text: {
                content
              }
            }
          ]
        }
      });
    } else {
      // Create new paragraph
      const contentBlock = {
        type: 'paragraph',
        paragraph: {
          rich_text: [
            {
              type: 'text',
              text: {
                content
              }
            }
          ]
        }
      };
      
      await notionClient.appendBlockChildren(memoryId, [contentBlock]);
    }
  }
  
  res.json({
    success: true,
    message: 'Memory entry updated successfully',
    id: memoryId
  });
}));

/**
 * Delete a memory entry (archive it)
 * DELETE /api/notion/memory-db/memory/:memoryId
 */
router.delete('/memory/:memoryId', asyncHandler(async (req, res) => {
  const { memoryId } = req.params;
  
  const errorMsg = validateParams({ memoryId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  // Archive the page (Notion's way of "deleting")
  await notionClient.updatePage(memoryId, { archived: true });
  
  res.json({
    success: true,
    message: 'Memory entry archived successfully',
    id: memoryId
  });
}));

// ============================================================================
// DATABASE ROUTES
// ============================================================================

/**
 * Get database details
 * GET /api/notion/memory-db/database/:databaseId
 */
router.get('/database/:databaseId', asyncHandler(async (req, res) => {
  const { databaseId } = req.params;
  
  const errorMsg = validateParams({ databaseId });
  if (errorMsg) {
    return res.status(400).json({ error: errorMsg });
  }
  
  const database = await notionClient.getDatabase(databaseId);
  
  // Extract database properties and schema
  const properties = {};
  for (const key in database.properties) {
    properties[key] = {
      id: database.properties[key].id,
      type: database.properties[key].type,
      name: key
    };
  }
  
  res.json({
    id: database.id,
    title: database.title.map(t => t.plain_text).join(''),
    description: database.description.map(t => t.plain_text).join(''),
    created_time: database.created_time,
    last_edited_time: database.last_edited_time,
    properties
  });
}));

/**
 * List all databases
 * GET /api/notion/memory-db/databases
 * Query params:
 *  - limit: Number of databases to return (default: 10)
 */
router.get('/databases', asyncHandler(async (req, res) => {
  const { limit = 10 } = req.query;
  
  // Search for databases
  const response = await notionClient.client.search({
    filter: {
      property: 'object',
      value: 'database'
    },
    page_size: parseInt(limit, 10)
  });
  
  // Extract database details
  const databases = response.results.map(db => ({
    id: db.id,
    title: db.title.map(t => t.plain_text).join(''),
    created_time: db.created_time,
    last_edited_time: db.last_edited_time,
    url: db.url
  }));
  
  res.json({
    databases,
    has_more: response.has_more
  });
}));

/**
