/**
 * page-utils.js
 * Utility functions for working with Notion pages
 */

const { NotionClient } = require('./api');

/**
 * Extracts the page title from a Notion page object
 * @param {Object} page - Notion page object
 * @returns {string} The page title or an empty string if not found
 */
function extractPageTitle(page) {
  if (!page || !page.properties) {
    return '';
  }

  // Try to find the title property
  // Notion pages typically have a "title" property or a property named "Title", "Name", etc.
  const titlePropertyNames = ['title', 'Title', 'Name', 'name'];
  
  // Look for a property with a title as the type
  for (const key in page.properties) {
    const property = page.properties[key];
    
    if (property.type === 'title' && property.title.length > 0) {
      return property.title.map(text => text.plain_text).join('');
    }
  }
  
  // If no title type found, look for properties with common title names
  for (const titleName of titlePropertyNames) {
    if (page.properties[titleName] && 
        page.properties[titleName].title && 
        page.properties[titleName].title.length > 0) {
      return page.properties[titleName].title.map(text => text.plain_text).join('');
    }
  }

  return '';
}

/**
 * Finds a page by its title in a specific database
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database to search
 * @param {string} title - Title to search for
 * @param {boolean} exactMatch - Whether to require an exact match (default: true)
 * @returns {Promise<Object|null>} The page object or null if not found
 */
async function findPageByTitle(notionClient, databaseId, title, exactMatch = true) {
  if (!notionClient || !databaseId || !title) {
    throw new Error('NotionClient, databaseId, and title are required');
  }

  // Create a filter for the database query based on whether we want exact matches
  const filter = exactMatch 
    ? {
        property: 'title',
        title: {
          equals: title
        }
      }
    : {
        property: 'title',
        title: {
          contains: title
        }
      };

  try {
    const response = await notionClient.queryDatabase(databaseId, filter);
    
    if (response.results && response.results.length > 0) {
      // If more than one result and exact match, prioritize exact matches
      if (response.results.length > 1 && exactMatch) {
        const exactMatches = response.results.filter(page => {
          const pageTitle = extractPageTitle(page);
          return pageTitle === title;
        });
        
        if (exactMatches.length > 0) {
          return exactMatches[0];
        }
      }
      
      return response.results[0];
    }
    
    return null;
  } catch (error) {
    throw new Error(`Error finding page by title: ${error.message}`);
  }
}

/**
 * Creates a unique title by adding incremental numbers if needed
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database to check against
 * @param {string} baseTitle - Original title to use as a base
 * @returns {Promise<string>} A unique title
 */
async function createUniqueTitle(notionClient, databaseId, baseTitle) {
  if (!notionClient || !databaseId || !baseTitle) {
    throw new Error('NotionClient, databaseId, and baseTitle are required');
  }

  // Try the base title first
  const basePageExists = await findPageByTitle(notionClient, databaseId, baseTitle);
  
  if (!basePageExists) {
    return baseTitle;
  }
  
  // Base title exists, try adding numbers
  let counter = 1;
  let uniqueTitle;
  let pageExists;
  
  do {
    uniqueTitle = `${baseTitle} ${counter}`;
    pageExists = await findPageByTitle(notionClient, databaseId, uniqueTitle);
    counter++;
  } while (pageExists);
  
  return uniqueTitle;
}

/**
 * Gets all pages from a database with optional filtering and sorting
 * @param {NotionClient} notionClient - Instance of NotionClient
 * @param {string} databaseId - ID of the database
 * @param {Object} filter - Optional filter criteria
 * @param {Array} sorts - Optional sort criteria
 * @returns {Promise<Array>} Array of page objects
 */
async function getAllPagesFromDatabase(notionClient, databaseId, filter = {}, sorts = []) {
  if (!notionClient || !databaseId) {
    throw new Error('NotionClient and databaseId are required');
  }

  try {
    const response = await notionClient.queryDatabase(databaseId, filter, sorts);
    return response.results || [];
  } catch (error) {
    throw new Error(`Error getting pages from database: ${error.message}`);
  }
}

/**
 * Creates a title property object for a Notion page
 * @param {string} titleName - The name of the title property in the database schema
 * @param {string} titleValue - The value to set for the title
 * @returns {Object} A properly formatted title property object
 */
function createTitleProperty(titleName, titleValue) {
  return {
    [titleName]: {
      title: [
        {
          type: 'text',
          text: {
            content: titleValue
          }
        }
      ]
    }
  };
}

/**
 * Extracts all property values from a page into a simplified object
 * @param {Object} page - Notion page object
 * @returns {Object} Simple key-value object with property names and values
 */
function extractPageProperties(page) {
  if (!page || !page.properties) {
    return {};
  }

  const properties = {};
  
  for (const key in page.properties) {
    const property = page.properties[key];
    
    switch (property.type) {
      case 'title':
        properties[key] = property.title.map(text => text.plain_text).join('');
        break;
      
      case 'rich_text':
        properties[key] = property.rich_text.map(text => text.plain_text).join('');
        break;
      
      case 'select':
        properties[key] = property.select?.name || null;
        break;
      
      case 'multi_select':
        properties[key] = property.multi_select?.map(item => item.name) || [];
        break;
      
      case 'date':
        properties[key] = property.date;
        break;
      
      case 'checkbox':
        properties[key] = property.checkbox;
        break;
      
      case 'number':
        properties[key] = property.number;
        break;
      
      case 'url':
        properties[key] = property.url;
        break;
      
      case 'email':
        properties[key] = property.email;
        break;
      
      case 'phone_number':
        properties[key] = property.phone_number;
        break;
      
      case 'formula':
        properties[key] = property.formula.type === 'string' 
          ? property.formula.string 
          : property.formula.number;
        break;
      
      case 'relation':
        properties[key] = property.relation.map(item => item.id);
        break;
      
      case 'people':
        properties[key] = property.people.map(person => person.id);
        break;
      
      default:
        properties[key] = null;
    }
  }
  
  return properties;
}

module.exports = {
  extractPageTitle,
  findPageByTitle,
  createUniqueTitle,
  getAllPagesFromDatabase,
  createTitleProperty,
  extractPageProperties
};

/**
 * Core Notion API wrapper
 * Handles authentication and basic Notion API requests
 */

const { Client } = require('@notionhq/client');

/**
 * NotionClient class provides a wrapper around the Notion API
 * with methods for common operations and error handling
 */
class NotionClient {
  /**
   * Initialize a new Notion client
   * @param {string} apiKey - Notion API integration secret key
   */
  constructor(apiKey) {
    if (!apiKey) {
      throw new Error('Notion API key is required');
    }
    
    this.client = new Client({
      auth: apiKey,
    });
  }

  /**
   * Generic error handler for Notion API calls
   * @param {Error} error - Error object from Notion API
   * @param {string} operation - Description of the operation that failed
   * @throws {Error} Re-throws the error with additional context
   */
  handleError(error, operation) {
    // Extract status code if available
    const statusCode = error.status || error.code;
    
    // Handle specific error types
    if (statusCode === 401) {
      throw new Error(`Authentication error: Invalid Notion API key`);
    } else if (statusCode === 404) {
      throw new Error(`Not found: The requested Notion resource does not exist`);
    } else if (statusCode === 429) {
      throw new Error(`Rate limit exceeded: Too many requests to Notion API`);
    }
    
    // For all other errors, add context and re-throw
    throw new Error(`Notion API error during ${operation}: ${error.message}`);
  }

  /**
   * Retrieve a Notion page by ID
   * @param {string} pageId - ID of the Notion page
   * @returns {Promise<Object>} Page object from Notion API
