## 6. Monitoring and Logging

### 6.1 Basic Logging

The application uses console logging by default. Add a dedicated logging directory:

```cmd
mkdir logs
```

Add this to your `.env` file:

```
LOG_LEVEL=info
LOG_FILE=./logs/app.log
```

Create a simple logging module `logger.js`:

```javascript
const fs = require('fs');
const util = require('util');

const LOG_LEVELS = {
  error: 0,
  warn: 1,
  info: 2,
  debug: 3
};

const LOG_LEVEL = process.env.LOG_LEVEL || 'info';
const LOG_FILE = process.env.LOG_FILE;

// Create log directory if it doesn't exist
if (LOG_FILE) {
  const logDir = LOG_FILE.substring(0, LOG_FILE.lastIndexOf('/'));
  if (!fs.existsSync(logDir)) {
    fs.mkdirSync(logDir, { recursive: true });
  }
}

function log(level, message, data) {
  if (LOG_LEVELS[level] <= LOG_LEVELS[LOG_LEVEL]) {
    const timestamp = new Date().toISOString();
    const logEntry = `[${timestamp}] ${level.toUpperCase()}: ${message}`;

    console[level](logEntry);

    if (data) {
      console[level](util.inspect(data, { depth: null, colors: true }));
    }

    if (LOG_FILE) {
      let logData = logEntry + (data ? '\n' + util.inspect(data, { depth: null }) : '') + '\n';
      fs.appendFileSync(LOG_FILE, logData);
    }
  }
}

module.exports = {
  error: (message, data) => log('error', message, data),
  warn: (message, data) => log('warn', message, data),
  info: (message, data) => log('info', message, data),
  debug: (message, data) => log('debug', message, data)
};
```

