### 6.3 API Endpoint Monitoring

Create a middleware to track API usage in `middleware/monitor.js`:

```javascript
const fs = require('fs');

// In-memory request tracking
const apiStats = {
  requests: 0,
  endpoints: {},
  errors: 0,
  lastReset: Date.now()
};

// Reset stats daily
setInterval(() => {
  const now = Date.now();
  if (now - apiStats.lastReset >= 86400000) { // 24 hours
    // Save daily report before reset
    const reportData = JSON.stringify({
      date: new Date().toISOString(),
      ...apiStats
    });
    fs.appendFileSync('./logs/api-daily-stats.json', reportData + '\n');

    // Reset stats
    apiStats.requests = 0;
    apiStats.endpoints = {};
    apiStats.errors = 0;
    apiStats.lastReset = now;
  }
}, 3600000); // Check hourly

function monitorMiddleware(req, res, next) {
  const startTime = Date.now();

  // Count request
  apiStats.requests++;

  // Track endpoint
  const endpoint = `${req.method} ${req.path}`;
  if (!apiStats.endpoints[endpoint]) {
    apiStats.endpoints[endpoint] = {
      count: 0,
      totalTime: 0,
      errors: 0
    };
  }

  // Track response
  const originalSend = res.send;
  res.send = function() {
    const endTime = Date.now();
    const responseTime = endTime - startTime;

    apiStats.endpoints[endpoint].count++;
    apiStats.endpoints[endpoint].totalTime += responseTime;

    if (res.statusCode >= 400) {
      apiStats.errors++;
      apiStats.endpoints[endpoint].errors++;
    }

    // Log slow requests (> 1 second)
    if (responseTime > 1000) {
      console.warn(`Slow response: ${endpoint} took ${responseTime}ms`);
    }

    return originalSend.apply(this, arguments);
  };

  next();
}

// Endpoint to get current stats
function getStats(req, res) {
  const stats = {
    uptime: process.uptime(),
    timestamp: Date.now(),
    ...apiStats
  };

  // Calculate averages
  Object.keys(stats.endpoints).forEach(endpoint => {
    const ep = stats.endpoints[endpoint];
    ep.avgTime = ep.count > 0 ? ep.totalTime / ep.count : 0;
  });

  res.json(stats);
}

module.exports = { monitorMiddleware, getStats };
```

