### 8.3 Logs Analysis

Create a simple log analyzer script:

```javascript
// analyze-logs.js
const fs = require('fs');
const readline = require('readline');

const logFile = process.argv[2] || './logs/app.log';
const errorCount = {};
const endpointStats = {};
let totalRequests = 0;
let errorRequests = 0;

const rl = readline.createInterface({
  input: fs.createReadStream(logFile),
  crlfDelay: Infinity
});

rl.on('line', (line) => {
  if (line.includes('ERROR')) {
    errorRequests++;

    // Extract error message
    const errorMatch = line.match(/ERROR: (.+)/);
    if (errorMatch) {
      const errorMsg = errorMatch[1];
      errorCount[errorMsg] = (errorCount[errorMsg] || 0) + 1;
    }
  }

  // Extract endpoint stats
  const requestMatch = line.match(/\[.+\] INFO: (GET|POST|PUT|PATCH|DELETE) (.+)/);
  if (requestMatch) {
    totalRequests++;
    const method = requestMatch[1];
    const path = requestMatch[2].split(' ')[0];
    const endpoint = `${method} ${path}`;

    if (!endpointStats[endpoint]) {
      endpointStats[endpoint] = 0;
    }
    endpointStats[endpoint]++;
  }
});

rl.on('close', () => {
  console.log(`Total Requests: ${totalRequests}`);
  console.log(`Error Requests: ${errorRequests} (${(errorRequests/totalRequests*100 || 0).toFixed(2)}%)`);

  console.log('\nTop 5 Errors:');
  Object.entries(errorCount)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .forEach(([error, count]) => {
      console.log(`- ${error}: ${count} occurrences`);
    });

  console.log('\nTop 5 Endpoints:');
  Object.entries(endpointStats)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .forEach(([endpoint, count]) => {
      console.log(`- ${endpoint}: ${count} requests`);
    });
});
```

Run it:

```cmd
node analyze-logs.js ./logs/app.log
```

