      ) : (
        messages.map((msg, index) => (
          <div key={index} className="message-group">
            {msg.type === 'user' ? (
              <UserMessage content={msg.content} />
            ) : (
              <AIMessage 
                content={msg.content} 
                personality={msg.personality || activePersonality} 
              />
            )}
          </div>
        ))
      )}
      <div ref={endOfMessagesRef} />
    </div>
  );
};

export default ConversationHistory;
