## 3. State Management with React Hooks

For a minimalist approach, we'll use React's built-in hooks for state management:

```jsx
// src/hooks/useConversation.js
import { useState, useCallback, useEffect } from 'react';
import { sendMessage } from '../services/api';

const useConversation = (initialPersonality = 'able') => {
  const [messages, setMessages] = useState([]);
  const [personality, setPersonality] = useState(initialPersonality);
  const [isProcessing, setIsProcessing] = useState(false);
  const [memories, setMemories] = useState({
    context: [],
    recent: []
  });

  // Load conversation history from localStorage on init
  useEffect(() => {
    const savedMessages = localStorage.getItem('conversationHistory');
    if (savedMessages) {
      try {
        setMessages(JSON.parse(savedMessages));
      } catch (e) {
        console.error('Failed to parse saved messages', e);
      }
    }
  }, []);

  // Save messages to localStorage when they change
  useEffect(() => {
    if (messages.length > 0) {
      localStorage.setItem('conversationHistory', JSON.stringify(messages));
    }
  }, [messages]);

  // Handle sending messages
  const handleSendMessage = useCallback(async (content) => {
    if (!content.trim()) return;

    // Add user message to history
    const userMessage = { type: 'user', content, timestamp: new Date().toISOString() };
    setMessages(prev => [...prev, userMessage]);

    // Set processing state
    setIsProcessing(true);

    try {
      // Send to API
      const response = await sendMessage(content, personality);

      // Add AI response to history
      const aiMessage = { 
        type: 'ai', 
        content: response.message, 
        personality,
        timestamp: new Date().toISOString()
      };

      setMessages(prev => [...prev, aiMessage]);

      // Update memories
      if (response.memories) {
        setMemories(response.memories);
      }
    } catch (error) {
      // Handle error
      console.error('Message sending failed:', error);
      setMessages(prev => [...prev, {
        type: 'ai',
        content: 'Sorry, I encountered an error. Please try again.',
        personality,
        timestamp: new Date().toISOString(),
        error: true
      }]);
    } finally {
      setIsProcessing(false);
    }
  }, [personality]);

  // Switch personality
  const switchPersonality = useCallback((newPersonality) => {
    setPersonality(newPersonality);

    // Add system message about personality change
    setMessages(prev => [...prev, {
      type: 'system',
      content: `Switched to ${newPersonality === 'able' ? 'AbleGPT' : 'RenascendGPT'}`,
      timestamp: new Date().toISOString()
    }]);
  }, []);

  // Clear conversation
  const clearConversation = useCallback(() => {
    if (window.confirm('Are you sure you want to clear the entire conversation?')) {
      setMessages([]);
      localStorage.removeItem('conversationHistory');
    }
  }, []);

  return {
    messages,
    personality,
    isProcessing,
    memories,
    handleSendMessage,
    switchPersonality,
    clearConversation
  };
};

export default useConversation;
```

## 4. API Integration

Create a service to handle API calls to your Next.js backend:

```jsx
// src/services/api.js
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || '/api';

/**
 * Send a message to the API
 * @param {string} message - User message
 * @param {string} personality - 'able' or 'renascend'
 * @returns {Promise} - API response
 */
export const sendMessage = async (message, personality) => {
  try {
    const response = await fetch(`${API_BASE_URL}/message`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        message,
        personality,
      }),
    });

    if (!response.ok) {
      throw new Error(`API error: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('API call failed:', error);
    throw error;
  }
};

/**
 * Fetch memory data
 * @param {string} personality - 'able' or 'renascend'
 * @returns {Promise} - Memory data
 */
export const fetchMemories = async (personality) => {
  try {
    const response = await fetch(`${API_BASE_URL}/memories?personality=${personality}`);

    if (!response.ok) {
      throw new Error(`API error: ${response.status}`);
    }

    return await response.json();
  } catch (error) {
    console.error('Memory fetch failed:', error);
    throw error;
  }
};
```

