## Introduction

This guide outlines a flexible framework for extending the server with new GPT personalities beyond the existing AbleGPT and RenascendGPT. The design follows minimalist principles to avoid over-engineering while ensuring scalability and maintainability.

## Abstract Personality Interface

The foundation of our extensible framework is a clean, abstract interface that all personality implementations must follow. We'll define this in TypeScript for type safety.

```typescript
// src/types/personality.ts

/**
 * Base interface for all GPT personalities
 */
export interface Personality {
  // Core identity properties
  id: string;                 // Unique identifier for the personality
  name: string;               // Human-readable name
  description: string;        // Brief description of the personality's purpose
  version: string;            // Semantic version of this personality implementation

  // Personality characteristics
  systemPrompt: string;       // Base system prompt for this personality
  defaultTemperature: number; // Default sampling temperature (0.0-1.0)
  maxTokens: number;          // Default max token limit

  // Behavior methods
  initialize(): Promise<void>;                     // Set up personality-specific resources
  preparePrompt(input: string, context?: any): Promise<string>; // Process user input before sending to LLM
  processResponse(response: string): Promise<string>;           // Process LLM response before sending to user
  getMemoryKey(input: string): string;             // Generate memory collection key for this input
  shutdown(): Promise<void>;                       // Clean up resources when shutting down
}

/**
 * Configuration for personality registration
 */
export interface PersonalityConfig {
  id: string;
  name: string;
  description: string;
  version: string;
  systemPrompt: string;
  defaultTemperature: number;
  maxTokens: number;
  memoryCollections?: string[];  // Names of memory collections this personality uses
  apiEndpoints?: string[];       // API endpoints this personality exposes
  uiComponents?: string[];       // UI component names this personality uses
}
```

This interface defines both the structure each personality must implement and the configuration used to register personalities with the system.

## Configuration Framework

Let's create a simple configuration framework to define personality parameters in a flexible way:

```typescript
// src/config/personalityConfig.ts

import { PersonalityConfig } from '../types/personality';

/**
 * Registry of all available personalities
 */
const personalityRegistry: Record<string, PersonalityConfig> = {};

/**
 * Register a new personality with the system
 */
export function registerPersonality(config: PersonalityConfig): void {
  if (personalityRegistry[config.id]) {
    console.warn(`Personality with ID ${config.id} already exists. Overwriting.`);
  }

  personalityRegistry[config.id] = config;
  console.log(`Registered personality: ${config.name} (${config.id})`);
}

/**
 * Get a personality configuration by ID
 */
export function getPersonalityConfig(id: string): PersonalityConfig | null {
  return personalityRegistry[id] || null;
}

/**
 * Get all registered personalities
 */
export function getAllPersonalities(): PersonalityConfig[] {
  return Object.values(personalityRegistry);
}

/**
 * Check if a personality exists
 */
export function personalityExists(id: string): boolean {
  return !!personalityRegistry[id];
}
```

This framework provides a simple registry for personalities, making it easy to add, retrieve, and validate personality configurations.

## Memory Management Integration

Each personality may need its own memory collections in ChromaDB. Here's how to integrate with the memory system:

```typescript
// src/services/personalityMemoryService.ts

import { Personality } from '../types/personality';
import ChromaClient from 'chromadb';

// Assuming a ChromaDB client is initialized elsewhere
import { chromaClient } from '../services/chromaService';

/**
 * Manages memory collections for personalities
 */
export class PersonalityMemoryManager {
  private personality: Personality;
  private collections: Map<string, any> = new Map();

  constructor(personality: Personality) {
    this.personality = personality;
  }

  /**
   * Initialize memory collections for this personality
   */
  async initialize(): Promise<void> {
    try {
      // Create or get the main collection for this personality
      const mainCollection = await this.getOrCreateCollection(
        `${this.personality.id}_main`
      );
      this.collections.set('main', mainCollection);

      // Create context-specific collections if needed
      await this.getOrCreateCollection(`${this.personality.id}_context`);
      await this.getOrCreateCollection(`${this.personality.id}_feedback`);

      console.log(`Initialized memory collections for ${this.personality.name}`);
    } catch (error) {
      console.error(`Failed to initialize memory for ${this.personality.id}:`, error);
      throw error;
    }
  }

  /**
   * Get or create a collection with the given name
   */
  async getOrCreateCollection(name: string): Promise<any> {
    try {
      // Try to get existing collection first
      let collection = await chromaClient.getOrCreateCollection({
        name,
        metadata: { 
          personality: this.personality.id,
          created: new Date().toISOString()
        }
      });

      this.collections.set(name, collection);
      return collection;
    } catch (error) {
      console.error(`Failed to create collection ${name}:`, error);
      throw error;
    }
  }

  /**
   * Store a memory in the specified collection
   */
  async storeMemory(
    collection: string, 
    text: string, 
    metadata: Record<string, any> = {}
  ): Promise<string> {
    const coll = this.collections.get(collection);
    if (!coll) {
      throw new Error(`Collection ${collection} not found`);
    }

    const id = `${this.personality.id}_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;

    await coll.add({
      ids: [id],
      documents: [text],
      metadatas: [{
        ...metadata,
        personality: this.personality.id,
        timestamp: new Date().toISOString()
      }]
    });

    return id;
  }

  /**
   * Query memories based on vector similarity
   */
  async queryMemories(
    collection: string,
    query: string,
    limit: number = 5
  ): Promise<any[]> {
    const coll = this.collections.get(collection);
    if (!coll) {
      throw new Error(`Collection ${collection} not found`);
    }

    const results = await coll.query({
      queryTexts: [query],
      nResults: limit
    });

    return results.documents[0].map((doc: string, i: number) => ({
      id: results.ids[0][i],
      text: doc,
      metadata: results.metadatas[0][i],
      distance: results.distances[0][i]
    }));
  }
}
```

This service provides the essential memory management functionality for each personality, including creating collections, storing memories, and querying similar memories.

## Personality Registration System

Now let's create a system for registering and loading personalities:

```typescript
// src/services/personalityService.ts

import { Personality, PersonalityConfig } from '../types/personality';
import { 
  registerPersonality,
  getPersonalityConfig,
  personalityExists 
} from '../config/personalityConfig';
import { PersonalityMemoryManager } from './personalityMemoryService';

// Map to store instantiated personalities
const personalities: Map<string, Personality> = new Map();

/**
 * Dynamically load a personality by its ID
 */
export async function loadPersonality(id: string): Promise<Personality> {
  // Check if already loaded
  if (personalities.has(id)) {
    return personalities.get(id)!;
  }

  // Check if personality exists in registry
  if (!personalityExists(id)) {
    throw new Error(`Personality with ID ${id} is not registered`);
  }

  try {
    // Dynamically import the personality module
    const module = await import(`../personalities/${id}/${id}.personality`);
    const config = getPersonalityConfig(id);

    if (!module.default || !config) {
      throw new Error(`Invalid personality module for ${id}`);
    }

    // Instantiate the personality
    const personality: Personality = new module.default(config);

    // Initialize the personality
    await personality.initialize();

    // Store for future use
    personalities.set(id, personality);

    return personality;
  } catch (error) {
    console.error(`Failed to load personality ${id}:`, error);
    throw error;
  }
}

/**
 * Register a new personality with the system
 */
export async function registerNewPersonality(
  config: PersonalityConfig, 
  implementation: any
): Promise<void> {
  // Register the configuration
  registerPersonality(config);

  // If implementation is provided directly, add it to the map
  if (implementation) {
    const personality = new implementation(config);
    await personality.initialize();
    personalities.set(config.id, personality);
  }
}

/**
 * Get a list of all available personalities
 */
export function getAvailablePersonalities(): string[] {
  return Array.from(personalities.keys());
}
```

This service handles the registration and dynamic loading of personalities, allowing new ones to be added easily.

## UI Integration

For integrating new personalities with the UI, we'll define a simple approach that leverages React components:

```typescript
// src/ui/hooks/usePersonality.ts

import { useState, useEffect } from 'react';
import { Personality } from '../../types/personality';
import { loadPersonality, getAvailablePersonalities } from '../../services/personalityService';

/**
 * Hook for working with personalities in React components
 */
export function usePersonality(initialId?: string) {
  const [currentPersonalityId, setCurrentPersonalityId] = useState<string | null>(initialId || null);
  const [personality, setPersonality] = useState<Personality | null>(null);
  const [availablePersonalities, setAvailablePersonalities] = useState<string[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<Error | null>(null);

  // Load the list of available personalities
  useEffect(() => {
    setAvailablePersonalities(getAvailablePersonalities());
  }, []);

  // Load the current personality
  useEffect(() => {
    if (!currentPersonalityId) return;

    setLoading(true);
    setError(null);

    loadPersonality(currentPersonalityId)
      .then(p => {
        setPersonality(p);
        setLoading(false);
      })
      .catch(err => {
        console.error(`Failed to load personality ${currentPersonalityId}:`, err);
        setError(err);
        setLoading(false);
      });
  }, [currentPersonalityId]);

  // Change the current personality
  const switchPersonality = (id: string) => {
    setCurrentPersonalityId(id);
  };

  return {
    personality,
    currentPersonalityId,
    availablePersonalities,
    loading,
    error,
    switchPersonality
  };
}
```

## Sample Implementation

Let's create a complete example personality from scratch:

```typescript
// src/personalities/research-gpt/research-gpt.personality.ts

import { Personality, PersonalityConfig } from '../../types/personality';
import { PersonalityMemoryManager } from '../../services/personalityMemoryService';
import { notionApi } from '../../routes/notion/notion-api';

/**
 * ResearchGPT - A personality focused on in-depth research and analysis
 */
export default class ResearchGPT implements Personality {
  id: string;
  name: string;
  description: string;
  version: string;
  systemPrompt: string;
  defaultTemperature: number;
  maxTokens: number;

  private memoryManager: PersonalityMemoryManager;

  constructor(config: PersonalityConfig) {
    this.id = config.id;
    this.name = config.name;
    this.description = config.description;
    this.version = config.version;
    this.systemPrompt = config.systemPrompt;
    this.defaultTemperature = config.defaultTemperature;
    this.maxTokens = config.maxTokens;

    this.memoryManager = new PersonalityMemoryManager(this);
  }

  async initialize(): Promise<void> {
    // Initialize memory collections
    await this.memoryManager.initialize();

    // Set up any Notion integration if needed
    try {
      // Check if we have access to the research database
      const researchDbId = process.env.RESEARCH_DB_ID;
      if (researchDbId) {
        await notionApi.retrieveDatabase(researchDbId);
        console.log("Successfully connected to research database");
      }
    } catch (error) {
      console.warn("Failed to connect to research database:", error);
      // Continue initialization even if Notion integration fails
    }
  }

  async preparePrompt(input: string, context?: any): Promise<string> {
    // Enhance the prompt with relevant research context
    let enhancedPrompt = input;

    // Add any relevant memories from past interactions
    try {
      const relevantMemories = await this.memoryManager.queryMemories('main', input, 3);

      if (relevantMemories && relevantMemories.length > 0) {
        enhancedPrompt = `${enhancedPrompt}\n\nRelevant context from previous research:\n`;

        for (const memory of relevantMemories) {
          enhancedPrompt += `- ${memory.text}\n`;
        }
      }
    } catch (error) {
      console.error("Error retrieving memories:", error);
    }

    // Add contextual information if available
    if (context && context.domain) {
      enhancedPrompt = `[Research Domain: ${context.domain}]\n${enhancedPrompt}`;
    }

    // Add a research-oriented framing to guide the response style
    enhancedPrompt = `As a research assistant, please provide well-structured information on this topic, citing sources when possible:\n\n${enhancedPrompt}`;

    return enhancedPrompt;
  }

  async processResponse(response: string): Promise<string> {
    // Store the response in memory for future reference
    await this.memoryManager.storeMemory('main', response, {
      type: 'research_response',
      timestamp: new Date().toISOString()
    });

    // Process the response to match the research personality style
    let processedResponse = response;

    // Ensure the response has a conclusion section if it's a longer analysis
    if (response.length > 500 && !response.includes("Conclusion") && !response.includes("Summary")) {
      processedResponse += "\n\n## Summary\nIn conclusion, this analysis provides an overview of the topic based on available research.";
    }

    return processedResponse;
  }

  getMemoryKey(input: string): string {
    // Generate a unique memory key based on input content
    return `research_${this.id}_${input.slice(0, 20).replace(/\W+/g, '_').toLowerCase()}`;
  }

  async shutdown(): Promise<void> {
    // Clean up resources
    console.log(`Shutting down ${this.name} personality`);
    // Nothing specific to clean up in this implementation
  }
}
```

