## Testing Approach

Testing new personalities requires a structured approach:

```typescript
// src/test/personality-test-framework.ts

import { Personality } from '../types/personality';

/**
 * Standard test suite for personalities
 */
export async function testPersonality(personality: Personality): Promise<boolean> {
  const testCases = [
    {
      name: 'Basic functionality',
      input: 'Hello world',
      assertion: async (response: string) => response.length > 0
    },
    {
      name: 'Memory integration',
      input: 'Remember this important fact: The sky is blue',
      followUp: 'What important fact did I ask you to remember?',
      assertion: async (response: string) => response.toLowerCase().includes('sky') && response.toLowerCase().includes('blue')
    },
    {
      name: 'Context handling',
      input: 'Tell me about this topic',
      context: { domain: 'astronomy' },
      assertion: async (response: string) => response.toLowerCase().includes('astronomy') || response.toLowerCase().includes('star') || response.toLowerCase().includes('planet')
    }
  ];

  console.log(`Testing personality: ${personality.name} (${personality.id})`);
  let allPassed = true;

  for (const test of testCases) {
    try {
      console.log(`Running test: ${test.name}`);

      // Prepare the prompt
      const preparedPrompt = await personality.preparePrompt(
        test.input, 
        test.context
      );

      // Simulate LLM response (in a real scenario, this would call the actual LLM)
      const mockLlmResponse = `This is a mock response to "${preparedPrompt}" from ${personality.name}`;

      // Process the response
      const processedResponse = await personality.processResponse(mockLlmResponse);

      // Check the assertion
      const passed = await test.assertion(processedResponse);

      if (passed) {
        console.log(`✅ Test passed: ${test.name}`);
      } else {
        console.error(`❌ Test failed: ${test.name}`);
        allPassed = false;
      }

      // If there's a follow-up test
      if (test.followUp) {
        const followUpPrompt = await personality.preparePrompt(test.followUp);
        const followUpMockResponse = `This is a follow-up response to "${followUpPrompt}"`;
        const followUpProcessed = await personality.processResponse(followUpMockResponse);

        const followUpPassed = await test.assertion(followUpProcessed);

        if (followUpPassed) {
          console.log(`✅ Follow-up test passed: ${test.name}`);
        } else {
          console.error(`❌ Follow-up test failed: ${test.name}`);
          allPassed = false;
        }
      }
    } catch (error) {
      console.error(`❌ Test error in ${test.name}:`, error);
      allPassed = false;
    }
  }

  console.log(`Testing complete for ${personality.name}. All tests passed: ${allPassed}`);
  return allPassed;
}
```

