runTests();
```

## How Components Work Together

The personality system uses several components that work together:

### 1. Registration Flow

```
┌───────────────┐     ┌───────────────────┐     ┌──────────────────┐
│ Personality   │     │ Personality       │     │ Personality      │
│ Implementation│────▶│ Registration      │────▶│ Configuration    │
│               │     │                   │     │ Registry         │
└───────────────┘     └───────────────────┘     └──────────────────┘
```

When the server starts:
1. Each personality's `index.ts` file is imported
2. The personality registers itself via `registerNewPersonality()`
3. The configuration is stored in the central registry

### 2. Interaction Flow

```
┌───────────┐     ┌───────────────┐     ┌──────────────┐     ┌───────────────┐
│ User      │     │ API Route     │     │ Personality  │     │ LLM Service   │
│ Request   │────▶│               │────▶│ Service      │────▶│               │
│           │     │               │     │              │     │               │
└───────────┘     └───────────────┘     └──────────────┘     └───────────────┘
                         │                     ▲                     │
                         │                     │                     │
                         ▼                     │                     ▼
                  ┌───────────────┐     ┌──────────────┐     ┌───────────────┐
                  │ Personality   │     │ Memory       │     │ Response      │
                  │ Instance      │────▶│ Manager      │     │ Processing    │
                  │               │     │              │◀────│               │
                  └───────────────┘     └──────────────┘     └───────────────┘
```

When a user interacts with a personality:
1. The request hits the API route for that personality
2. The personality is loaded from the registry (if not already loaded)
3. The personality prepares the prompt using its `preparePrompt()` method
4. The prompt is sent to the LLM service
5. The response is processed by the personality's `processResponse()` method
6. Relevant information is stored in memory for future reference
7. The processed response is returned to the user

## Integration with AbleGPT and RenascendGPT

Your existing personalities (AbleGPT and RenascendGPT) can be integrated with this system by implementing the Personality interface:

### 1. Create Interface Adapters

Create adapter classes that adapt your existing personality implementations to the new interface:

```typescript
// src/personalities/able-gpt/able-gpt.personality.ts

import { Personality, PersonalityConfig } from '../../types/personality';
import { PersonalityMemoryManager } from '../../services/personalityMemoryService';
import { existingAbleGptService } from '../../services/legacy/ableGptService';

export default class AbleGPTAdapter implements Personality {
  id: string;
  name: string;
  description: string;
  version: string;
  systemPrompt: string;
  defaultTemperature: number;
  maxTokens: number;

  private memoryManager: PersonalityMemoryManager;

  constructor(config: PersonalityConfig) {
    this.id = config.id;
    this.name = config.name;
    this.description = config.description;
    this.version = config.version;
    this.systemPrompt = config.systemPrompt;
    this.defaultTemperature = config.defaultTemperature;
    this.maxTokens = config.maxTokens;

    this.memoryManager = new PersonalityMemoryManager(this);
  }

  async initialize(): Promise<void> {
    await this.memoryManager.initialize();
    await existingAbleGptService.initialize();
  }

  async preparePrompt(input: string, context?: any): Promise<string> {
    // Call the existing AbleGPT implementation
    return existingAbleGptService.preparePrompt(input, context);
  }

  async processResponse(response: string): Promise<string> {
    // Call the existing AbleGPT implementation
    return existingAbleGptService.processResponse(response);
  }

  getMemoryKey(input: string): string {
    return `able_gpt_${input.slice(0, 20).replace(/\W+/g, '_').toLowerCase()}`;
  }

  async shutdown(): Promise<void> {
    await existingAbleGptService.cleanup();
  }
}
```

### 2. Register the Adapted Personalities

```typescript
// src/personalities/able-gpt/index.ts

import { registerNewPersonality } from '../../services/personalityService';
import AbleGPTAdapter from './able-gpt.personality';

// Use the existing system prompt from your current implementation
const existingSystemPrompt = process.env.ABLE_GPT_SYSTEM_PROMPT || "Default AbleGPT system prompt";

registerNewPersonality({
  id: 'able-gpt',
  name: 'AbleGPT',
  description: 'A highly capable assistant for general tasks',
  version: '2.0.0', // Increment version to reflect the adaptation
  systemPrompt: existingSystemPrompt,
  defaultTemperature: 0.7,
  maxTokens: 1024,
  memoryCollections: ['main', 'context'],
  apiEndpoints: ['/api/chat', '/api/assist'],
  uiComponents: ['ChatInterface', 'AssistPanel']
}, AbleGPTAdapter);

export { default as AbleGPT } from './able-gpt.personality';
```

## Quick Start Guide

To quickly implement a new personality, follow these steps:

