   import { Personality, PersonalityConfig } from '../../types/personality';
   import { PersonalityMemoryManager } from '../../services/personalityMemoryService';

   export default class MyNewGPT implements Personality {
     // Implement required properties and methods
     // (See the Sample Implementation section for a complete example)
   }
   ```

3. **Create the registration file**:
   ```typescript
   // src/personalities/my-new-gpt/index.ts

   import { registerNewPersonality } from '../../services/personalityService';
   import MyNewGPT from './my-new-gpt.personality';

   registerNewPersonality({
     id: 'my-new-gpt',
     name: 'My New GPT',
