    if (this.enabled && (options.autoCleanup !== false)) {
      this.startPeriodicCleanup();
      console.log(`🧠 Cache initialized: enabled=${this.enabled}, ttl=${this.ttl}ms, maxItems=${this.maxItems}`);
    } else {
      console.log(`🧠 Cache initialized: enabled=${this.enabled} (auto cleanup is OFF)`);
    }
  }
  
  /**
   * Starts periodic cleanup of expired cache items
