  clear() {
    if (!this.enabled) {
      return;
    }
    
    for (const storeType in this.stores) {
      const count = this.stores[storeType].size;
      this.stores[storeType].clear();
      logger.debug(`Cache cleared: ${storeType} store (${count} items)`);
