      const stats = Object.entries(this.stores)
        .map(([type, store]) => `${type}: ${store.size}`)
        .join(', ');
        
      logger.debug(`Cache cleanup completed. Removed ${totalRemoved} items. Current sizes: ${stats}`);
    }
    
    return totalRemoved;
  }
  
  /**
   * Returns statistics about the cache stores
   * @returns {Object} Object containing the size of each cache store and hit/miss stats
   */
  getStats() {
    const storeStats = {};
    for (const [type, store] of Object.entries(this.stores)) {
