/**
 * @route   GET /query-database
 * @desc    Queries the configured Notion database and returns entries
 * @query   {number} limit - Maximum number of entries to return
 * @returns {Object} JSON response with database entries
 */
router.get("/query-database", async (req, res) => {
  try {
    const { limit = CONFIG.DEFAULT_PAGE_SIZE } = req.query;

    if (!notionDatabaseId) {
      logger.warn("Missing database ID", { databaseId: notionDatabaseId }, req.requestId);
      return res.status(400).json({ error: "Missing NOTION_DATABASE_ID in environment variables." });
    }
    
    const parsedLimit = parseInt(limit, 10);
    if (isNaN(parsedLimit) || parsedLimit < 1) {
      logger.warn("Invalid limit parameter", { limit }, req.requestId);
      return res.status(400).json({ error: "Invalid limit parameter. Must be a positive number." });
    }

    logger.info(`Querying database with limit=${parsedLimit}`, { databaseId: notionDatabaseId, limit: parsedLimit }, req.requestId);
    const response = await apiCallWithRetry(() => 
      notionApi.post(`/databases/${notionDatabaseId}/query`, {
        page_size: parsedLimit
      })
    , { requestId: req.requestId });

    const { extractPageTitle } = require('./page-utils');
    const rows = await Promise.all(response.data.results.map(async (item) => {
      try {
        const title = await extractPageTitle(item) || `Untitled (${item.id.substring(0, 8)})`;

        return {
          title,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null
        };
      } catch (err) {
        logger.error(`Error processing database item ${item.id}`, err, req.requestId);
        return {
          title: `Error (${item.id.substring(0, 8)})`,
          id: item.id,
          type: item.object,
          parent: item.parent?.database_id || null,
          url: item.url || null,
          error: true
        };
      }
    }));

    logger.info(`Database query returned ${rows.length} results`, { count: rows.length }, req.requestId);
    res.json({ success: true, count: rows.length, entries: rows });
  } catch (error) {
    logger.error("Database query failed", error, req.requestId);
    handleApiError(res, error, "query-database");
  }
});

/**
 * @route   GET /health
 * @desc    Health check endpoint for Notion integration
 * @returns {Object} JSON response with health status
 */
router.get("/health", async (req, res) => {
  try {
    const { notionParentPageId } = require('./config');

    logger.debug("Processing health check request", null, req.requestId);
    
    // Check if Notion API is accessible
    let notionApiStatus = 'healthy';
    let notionApiMessage = 'Connected to Notion API';
    
    try {
      const response = await apiCallWithRetry(() => notionApi.get('/users/me'), {
        maxRetries: 1,
        requestId: req.requestId
      });
      
      if (!response || !response.data) {
        notionApiStatus = 'degraded';
        notionApiMessage = 'Received empty response from Notion API';
      }
    } catch (apiError) {
      notionApiStatus = 'unhealthy';
      notionApiMessage = apiError.message || 'Failed to connect to Notion API';
      logger.error('Health check: Notion API connection failed', apiError, req.requestId);
    }
    
    // Check missing environment variables
    if (missingEnvVars.length > 0) {
      notionApiStatus = notionApiStatus === 'healthy' ? 'degraded' : notionApiStatus;
      notionApiMessage += `. Missing environment variables: ${missingEnvVars.join(', ')}`;
      logger.warn("Health check: Missing environment variables", { missingVars: missingEnvVars }, req.requestId);
    }
    
    // Check if parent page exists
    let parentPageStatus = 'unknown';
    if (notionApiStatus !== 'unhealthy' && notionParentPageId) {
      try {
        await apiCallWithRetry(() => notionApi.get(`/pages/${notionParentPageId}`), {
          maxRetries: 1,
          requestId: req.requestId
        });
        parentPageStatus = 'valid';
      } catch (error) {
        logger.error("Health check: Parent page is invalid or inaccessible", error, req.requestId);
        notionApiStatus = notionApiStatus === 'healthy' ? 'degraded' : notionApiStatus;
        notionApiMessage += '. Parent page ID is invalid or inaccessible';
        parentPageStatus = 'invalid';
      }
    }
    
    // Include cache stats
    const cacheStats = getCacheStats();
    
    // Include rate limiter stats
    const rateLimitStats = getRateLimitStats();
    
    // Get feature status
    const featureStatus = { ...FEATURES };
    
    logger.info("Health check completed", { 
      status: notionApiStatus, 
      cacheStats, 
      rateLimitStats,
      featureStatus
    }, req.requestId);
    
    const responseStatus = notionApiStatus === 'unhealthy' ? 503 : 200;
    
    res.status(responseStatus).json({ 
      status: notionApiStatus, 
      message: notionApiMessage,
      version: '1.0.0',
      timestamp: new Date().toISOString(),
      cache: cacheStats,
      rateLimits: rateLimitStats,
      features: featureStatus,
      environment: {
        parentPage: parentPageStatus,
        missingVars: missingEnvVars.length > 0 ? missingEnvVars : null,
        configuredVars: requiredEnvVars.filter(v => !missingEnvVars.includes(v))
      }
    });
  } catch (error) {
    logger.error("Health check failed", error, req.requestId);
    res.status(503).json({ 
      status: 'unhealthy', 
      message: 'Unable to complete health check',
      error: error.message,
      timestamp: new Date().toISOString()
    });
  }
});

