 */
router.put("/post-standalone-page", async (req, res) => {
  try {
    const { title, content } = req.body;
    logger.info(`Received request to create standalone page with title: ${title}`, 
      { title, hasContent: !!content }, req.requestId);

    // Input validation
    if (!title) {
      logger.warn("Missing title for standalone page", null, req.requestId);
      return res.status(400).json({ error: "Missing title." });
    }
    
    if (typeof title !== 'string') {
      logger.warn("Invalid title type for standalone page", { titleType: typeof title }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid title. Must be a string." 
      });
    }
    
    if (content && typeof content !== 'string' && !Array.isArray(content)) {
      logger.warn("Invalid content type for standalone page", 
        { contentType: typeof content, isArray: Array.isArray(content) }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid content. Must be a string or an array of blocks if provided." 
      });
    }
    
    const sanitizedTitle = sanitizeInput(title);

    if (!sanitizedTitle) {
      logger.warn("Empty title after sanitization", { title }, req.requestId);
      return res.status(400).json({ error: "Title cannot be empty after sanitization." });
    }

    // Start with a heading for the title
    const childrenBlocks = [createHeadingBlock(sanitizedTitle)];
    
    // Add content if provided - process into blocks
    if (content) {
      const contentBlocks = processContentToBlocks(content);
      childrenBlocks.push(...contentBlocks);
      
      // Log whether we processed markdown or block format
      const contentFormat = isBlockFormat(content) ? 'block' : 'markdown';
      logger.info(`Processed content as ${contentFormat} format`, 
        { contentFormat, blockCount: contentBlocks.length }, req.requestId);
    }
    
    logger.info(`Creating standalone page titled "${sanitizedTitle}"`, 
      { blockCount: childrenBlocks.length }, req.requestId);
      
    const response = await apiCallWithRetry(() => 
      notionApi.post('/pages', {
        parent: { type: "page_id", page_id: notionParentPageId },
        properties: {
          title: [
            {
              type: "text",
              text: { content: sanitizedTitle }
            }
          ]
        },
        children: childrenBlocks
      })
    , { requestId: req.requestId });

    const pageId = response.data.id;
    logger.info(`Successfully created standalone page with title "${sanitizedTitle}"`, 
      { pageId }, req.requestId);

    // Invalidate cache
    cache.clear();

    res.json({ 
      success: true, 
      pageId,
      message: "Standalone page created successfully"
    });
  } catch (error) {
    logger.error("Error creating standalone page", error, req.requestId);
    handleApiError(res, error, "create-standalone-page");
  }
});

