router.delete("/page/:id", async (req, res) => {
  try {
    const pageId = req.params.id;
    
    if (!pageId) {
      logger.warn("Missing page ID for archive operation", null, req.requestId);
      return res.status(400).json({ error: "Missing page ID." });
    }
    
    // Validate pageId format
    if (!pageId.match(/^[a-f0-9-]+$/i)) {
      logger.warn("Invalid pageId format", { pageId }, req.requestId);
      return res.status(400).json({ 
        error: "Invalid pageId format. Must be a valid Notion page ID." 
      });
    }

    logger.info(`Archiving page with ID ${pageId}`, { pageId }, req.requestId);
    await apiCallWithRetry(() => 
      notionApi.patch(`/pages/${pageId}`, {
        archived: true
      })
    , { requestId: req.requestId });

    // Invalidate cache
    cache.invalidate(pageId);
    logger.info(`Successfully archived page with ID ${pageId}`, { pageId }, req.requestId);
    
    // Also remove any entries in the titles cache that might reference this page
    for (const [key] of Object.entries(cache.stores.titles)) {
      if (key === pageId) {
        cache.invalidate(key, 'titles');
        logger.debug(`Invalidated title cache for page ID ${pageId}`, null, req.requestId);
        break;
      }
    }

    res.json({ 
      success: true, 
      archived: true,
      message: `Page ${pageId} archived successfully`
    });
  } catch (error) {
    logger.error("Error archiving page", error, req.requestId);
    handleApiError(res, error, "archive-page");
  }
});

