/**
 * Notion Page Utilities
 * 
 * This module provides functions for working with Notion pages, including:
 * - Page title extraction from various Notion objects
 * - Finding pages by title with caching support
 * - Recursive child page extraction
 * - Helper functions for parsing Notion page data
 */

const { notionApi, apiCallWithRetry, sanitizeInput } = require('./api-utils');
const { cache } = require('./cache');
const { CONFIG, FEATURES } = require('./config');
const logger = require('./logger');

/**
 * Extracts the title from a Notion page object with caching
 * 
 * @param {Object} page - The Notion page object
 * @param {Object} [options] - Options for extraction
 * @param {string} [options.requestId] - Optional request ID for logging
 * @returns {Promise<string>} - The extracted page title or a default title
 */
async function extractPageTitle(page, options = {}) {
  if (!page) {
    logger.warn("Cannot extract title: page object is undefined", null, options.requestId);
    return "Untitled Page";
  }
  
  // Check cache first if enabled
  const cacheKey = page.id;
  if (FEATURES.CACHE_ENABLED && cacheKey) {
    const cachedTitle = cache.get(cacheKey, 'titles');
    if (cachedTitle) {
      logger.debug(`Title cache hit for page ${cacheKey}`, null, options.requestId);
      return cachedTitle;
    }
    logger.debug(`Title cache miss for page ${cacheKey}`, null, options.requestId);
  } else if (!cacheKey) {
    logger.warn("Cannot cache page title: missing page ID", null, options.requestId);
  }

  // Extract title using helper function
  const extractedTitle = await extractTitleUncached(page, options);
  
  // Cache the result if caching is enabled
  if (FEATURES.CACHE_ENABLED && extractedTitle && cacheKey) {
    cache.set(cacheKey, extractedTitle, 'titles');
    logger.debug(`Cached title for page ${cacheKey}: "${extractedTitle}"`, null, options.requestId);
  }

  return extractedTitle;
}

/**
 * Helper function for title extraction that attempts multiple strategies
 * 
 * @param {Object} page - The Notion page object
 * @param {Object} [options] - Options for extraction
 * @param {string} [options.requestId] - Optional request ID for logging
 * @returns {Promise<string>} - The extracted page title or a default title
 */
async function extractTitleUncached(page, options = {}) {
  // Try to extract title from properties first (for pages and databases)
  if (page.properties) {
    // Check all title-like properties in descending order of likelihood
    const titleProps = ['title', 'Name', 'Feature', 'Title'];

    for (const prop of titleProps) {
      const titleArray = page.properties[prop]?.title;
      if (titleArray && titleArray.length > 0) {
        const textContent = titleArray[0]?.plain_text || titleArray[0]?.text?.content;
        if (textContent) {
          logger.debug(`Found title in properties.${prop}: "${textContent}"`, null, options.requestId);
          return textContent;
        }
      }
    }
  }

  // For direct title property (older Notion API format)
  if (page.title) {
    if (Array.isArray(page.title) && page.title.length > 0) {
      const textContent = page.title[0]?.plain_text || page.title[0]?.text?.content;
      if (textContent) {
        logger.debug(`Found title in direct title array: "${textContent}"`, null, options.requestId);
        return textContent;
      }
    } else if (typeof page.title === 'string') {
      logger.debug(`Found string title: "${page.title}"`, null, options.requestId);
      return page.title;
    }
  }

  // Try to get from page object
  if (page.child_page?.title) {
    logger.debug(`Found title in child_page: "${page.child_page.title}"`, null, options.requestId);
    return page.child_page.title;
  }

  // Last resort: Extract from page content
  if (page.id) {
    try {
      return await extractTitleFromBlocks(page.id, options);
    } catch (err) {
      logger.error(`Failed to extract title from blocks for ${page.id}`, err, options.requestId);
      return `Untitled Page (${page.id.substring(0, 8)})`;
    }
  }

  return `Untitled Page (${page.id ? page.id.substring(0, 8) : 'unknown'})`;
}

/**
 * Extracts title from a page's blocks by examining their content
 * 
 * @param {string} pageId - The Notion page ID
 * @param {Object} [options] - Options for extraction
 * @param {string} [options.requestId] - Optional request ID for logging
 * @returns {Promise<string>} - The extracted title or a default title
 */
async function extractTitleFromBlocks(pageId, options = {}) {
  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=50`)
    , { requestId: options.requestId });

    const blocks = response.data.results;

    // First check for a child_page with title
    const childPageBlock = blocks.find(block => block.type === "child_page");
    if (childPageBlock?.child_page?.title) {
      const title = childPageBlock.child_page.title;
      logger.debug(`Found child page title: ${title}`, null, options.requestId);
      return title;
    }

    // Look for the first heading block
    const headingTypes = ["heading_1", "heading_2", "heading_3"];
    const headingBlock = blocks.find(block => headingTypes.includes(block.type));

    if (headingBlock) {
      const blockType = headingBlock.type;
      const richText = headingBlock[blockType]?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        logger.debug(`Found title in ${blockType}: "${title}"`, null, options.requestId);
        return title;
      }
    }

    // Try to get first paragraph text as fallback
    const paragraphBlock = blocks.find(block => block.type === "paragraph");
    if (paragraphBlock) {
      const richText = paragraphBlock.paragraph?.rich_text || [];
      const title = richText.map(rt => rt.text?.content || '').join("").trim();

      if (title) {
        logger.debug(`Found title in paragraph: "${title}"`, null, options.requestId);
        return title;
      }
    }

    // Get page info directly as last resort
    try {
      const pageInfo = await apiCallWithRetry(() => 
        notionApi.get(`/pages/${pageId}`)
      , { requestId: options.requestId });

      // Try to find any property that might contain a title
      const properties = pageInfo.data.properties;
      if (properties) {
        for (const [key, value] of Object.entries(properties)) {
          if (value.title && value.title.length > 0) {
            const title = value.title[0]?.plain_text || value.title[0]?.text?.content;
            if (title) {
              logger.debug(`Found title in page properties.${key}: "${title}"`, null, options.requestId);
              return title;
            }
          }
        }
      }
    } catch (err) {
      logger.error(`Failed to fetch page info for ${pageId}`, err, options.requestId);
    }

    logger.warn(`No usable title found for ${pageId}`, null, options.requestId);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  } catch (err) {
    logger.error(`Title extraction failed for ${pageId}`, err, options.requestId);
    return `Untitled Page (${pageId.substring(0, 8)})`;
  }
}

/**
 * Finds a Notion page by its title with caching support
 * 
 * @param {string} title - The page title to search for
 * @param {Object} [options] - Options for finding the page
 * @param {string} [options.requestId] - Optional request ID for logging
 * @param {boolean} [options.exactMatch=false] - Whether to require an exact match
 * @returns {Promise<Object|null>} - Object containing page data and title, or null if not found
 */
async function findPageByTitle(title, options = {}) {
  title = sanitizeInput(title);
  const requestId = options.requestId;
  const exactMatch = options.exactMatch === true;
  
  if (!title) {
    logger.warn("Empty title provided to findPageByTitle", null, requestId);
    return null;
  }
  
  const normalizedInput = title.toLowerCase();
  
  // Check cache first if enabled
  if (FEATURES.CACHE_ENABLED) {
    const cacheKey = `title:${normalizedInput}`;
    const cachedPage = cache.get(cacheKey);
    if (cachedPage) {
      logger.debug(`Cache hit for title: "${title}"`, null, requestId);
      return cachedPage;
    }
    logger.debug(`Cache miss for title: "${title}"`, null, requestId);
  }
  
  try {
    logger.info(`Searching for page titled "${title}"`, 
      { exactMatch, normalizedInput }, requestId);
      
    const searchResponse = await apiCallWithRetry(() => 
      notionApi.post('/search', {
        query: title,
        filter: { property: "object", value: "page" },
        page_size: 10
      })
    , { requestId });

    // No results
    if (!searchResponse.data.results.length) {
      logger.info(`No results found for title "${title}"`, null, requestId);
      return null;
    }

    // Use the enhanced title extraction for better matching
    const pages = await Promise.all(searchResponse.data.results.map(async (page) => {
      try {
        const extractedTitle = await extractPageTitle(page, { requestId });
        return {
          page,
          title: extractedTitle
        };
      } catch (err) {
        logger.error(`Error extracting title for page ${page.id}`, err, requestId);
        return {
          page,
          title: `Untitled (${page.id.substring(0, 8)})`
        };
      }
    }));

    // Find exact match or closest match
    const exactMatchItem = pages.find(item => 
      item.title && item.title.toLowerCase() === normalizedInput
    );
    
    // If exact match is required and none found, return null
    if (exactMatch && !exactMatchItem) {
      logger.info(`No exact match found for title "${title}"`, null, requestId);
      return null;
    }
    
    const match = exactMatchItem || pages[0] || null;
    
    if (match) {
      logger.info(`Found ${exactMatchItem ? 'exact' : 'closest'} match: "${match.title}"`, 
        { pageId: match.page.id }, requestId);
    }
    
    // Cache the result if enabled
    if (FEATURES.CACHE_ENABLED && match) {
      const cacheKey = `title:${normalizedInput}`;
      cache.set(cacheKey, match);
      logger.debug(`Cached page result for title: "${title}"`, null, requestId);
    }
    
    return match;
  } catch (error) {
    logger.error(`Error finding page for "${title}"`, error, requestId);
    return null;
  }
}

/**
 * Recursively extracts child pages from a Notion page with duplicate detection
 * and controlled concurrency
 * 
 * @param {string} pageId - The parent page ID to extract children from
 * @param {Array} [pages=[]] - Accumulator for child pages
 * @param {Set} [visited=new Set()] - Set of already visited page IDs to prevent loops
 * @param {Object} [options] - Options for extraction
 * @param {number} [options.depth=0] - Current recursion depth
 * @param {number} [options.maxDepth=3] - Maximum recursion depth
 * @param {string} [options.requestId] - Optional request ID for logging
 * @returns {Promise<Array>} - Array of child page objects
 */
async function extractChildPages(pageId, pages = [], visited = new Set(), options = {}) {
  const depth = options.depth || 0;
  const maxDepth = options.maxDepth || 3;
  const requestId = options.requestId;
  
  // Guard against invalid pageId or excessive recursion
  if (!pageId || visited.has(pageId) || depth > maxDepth) {
    return pages;
  }
  
  // Protect against infinite recursion
  visited.add(pageId);
  
  // Track recursion depth for debugging
  const indentation = "  ".repeat(depth);
  logger.debug(`${indentation}Exploring page ${pageId} (depth: ${depth}/${maxDepth})`, null, requestId);

  try {
    const response = await apiCallWithRetry(() => 
      notionApi.get(`/blocks/${pageId}/children?page_size=100`)
    , { requestId });

    const blocks = response.data.results;
    
    const blockCount = blocks.length;
    logger.debug(`${indentation}Found ${blockCount} blocks in page ${pageId}`, null, requestId);

    // Process child pages specifically
    const childPagePromises = blocks
      .filter(block => block.type === "child_page")
      .map(async (block) => {
        const childId = block.id;
        
        // Skip if we already added this page
        if (pages.some(p => p.id === childId)) {
          logger.debug(`${indentation}Duplicate page detected: ${childId}`, null, requestId);
          return null;
        }
        
        let childTitle = block.child_page?.title;

        // If no title in the initial response, try to extract it
        if (!childTitle || childTitle === "(no title)") {
          try {
            const extractOptions = { requestId };
            const pageInfo = await apiCallWithRetry(() => 
              notionApi.get(`/pages/${childId}`)
            , { requestId });
            childTitle = await extractPageTitle(pageInfo.data, extractOptions) || 
                         childTitle || 
                         "(no title)";
          } catch (err) {
            logger.error(`${indentation}Failed to fetch child page info for ${childId}`, err, requestId);
            childTitle = `Untitled (${childId.substring(0, 8)})`;
          }
        }

        logger.debug(`${indentation}Found child page: ${childTitle} (ID: ${childId})`, null, requestId);
        
        return {
          id: childId,
          title: childTitle,
          parent: pageId,
          type: "page"
        };
      });
    
    // Wait for all promises to resolve and filter out nulls
    const childPages = (await Promise.all(childPagePromises)).filter(Boolean);
    
    // Add the child pages to our results
    for (const childPage of childPages) {
      pages.push(childPage);
    }

    // Process nested pages with controlled concurrency (max 3 concurrent requests)
    if (depth < maxDepth) {
      const batchSize = 3;
      for (let i = 0; i < childPages.length; i += batchSize) {
        const batch = childPages.slice(i, i + batchSize);
        await Promise.all(
          batch.map(child => 
            extractChildPages(child.id, pages, visited, {
              depth: depth + 1,
              maxDepth,
              requestId
            })
          )
        );
      }
    }

    return pages;
  } catch (err) {
    logger.error(`${indentation}Failed to fetch children for ${pageId}`, err, requestId);
    return pages;
  }
}

/**
 * Normalizes a page object to a consistent format with essential properties
 * 
 * @param {Object} page - The Notion page object to normalize
 * @param {string} [title] - Optional pre-extracted title
 * @param {Object} [options] - Options for normalization
 * @param {string} [options.requestId] - Optional request ID for logging
 * @returns {Promise<Object>} - Normalized page object with id, title, type, etc.
 */
async function normalizePage(page, title = null, options = {}) {
  if (!page) return null;
  
  try {
    const pageTitle = title || await extractPageTitle(page, options);
    
    return {
      id: page.id,
      title: pageTitle,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
      url: page.url || null,
      createdTime: page.created_time,
      lastEditedTime: page.last_edited_time
    };
  } catch (err) {
    logger.error(`Error normalizing page ${page.id}`, err, options.requestId);
    return {
      id: page.id,
      title: `Error (${page.id.substring(0, 8)})`,
      type: page.object || 'page',
      parent: page.parent?.page_id || page.parent?.database_id || null,
      url: page.url || null,
      error: true
    };
  }
}

module.exports = {
  extractPageTitle,
  extractTitleFromBlocks,
  findPageByTitle,
  extractChildPages,
  normalizePage
};

/**
 * Notion Rate Limiter
 * 
 * This module provides rate limiting functionality for the Notion API to respect
 * the API's limits of 3 requests per second overall and varying limits for different
 * operation types.
 */

const { FEATURES, CONFIG } = require('./config');
const logger = require('./logger');

/**
 * Token bucket rate limiter for the Notion API
 * Handles:
 * - 3 requests per second per token overall
 * - Request queueing with promise resolution
 * - Dynamic adjustment based on rate limit headers
 */
class NotionRateLimiter {
  /**
   * Creates a new NotionRateLimiter instance
   * @param {Object} options - Rate limiter configuration
   * @param {number} [options.maxTokens=5] - Maximum number of tokens (requests per second)
   * @param {number} [options.refillRate=5] - Tokens to add per second
   * @param {number} [options.queueCheckInterval=100] - Interval to check queue in ms
   */
  constructor(options = {}) {
    this.enabled = FEATURES.RATE_LIMITING_ENABLED;
    this.maxTokens = options.maxTokens || CONFIG.RATE_LIMIT_MAX_TOKENS;
    this.refillRate = options.refillRate || CONFIG.RATE_LIMIT_REFILL_RATE;
    this.queueCheckInterval = options.queueCheckInterval || CONFIG.RATE_LIMIT_QUEUE_CHECK_INTERVAL;
    this.tokens = this.maxTokens;
    this.lastRefill = Date.now();
    this.queued = [];
    this.processing = false;
    
    // Track different operation types for more specific rate limiting
    this.operationLimits = {
      read: { tokens: 3, maxTokens: 3, lastRefill: Date.now() },     // 3 req/sec for reads
      write: { tokens: 2, maxTokens: 2, lastRefill: Date.now() }     // 2 req/sec for writes
    };
    
    // Track per-minute limits
    this.minuteLimits = {
      write: { 
        count: 0, 
        resetTime: Date.now() + 60000,
        max: 30   // 30 req/min for writes
      }
    };
    
    // Set up automatic queue processing
    this.queueInterval = setInterval(() => {
      if (this.queued.length > 0 && !this.processing) {
        this.processQueue();
      }
    }, this.queueCheckInterval);

    if (this.enabled) {
      console.log(`🚦 Rate limiter initialized: maxTokens=${this.maxTokens}, refillRate=${this.refillRate}/sec`);
    } else {
      console.log('🚦 Rate limiter is DISABLED via feature flag');
    }
  }
  
  /**
   * Refills tokens based on time elapsed since last refill
   * @private
   */
  refillTokens() {
    const now = Date.now();
    const timePassed = now - this.lastRefill;
    
    if (timePassed >= 1000) {
      const secondsPassed = timePassed / 1000;
      const tokensToAdd = Math.floor(secondsPassed * this.refillRate);
      
      if (tokensToAdd > 0) {
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;
        
        // Also refill operation-specific tokens
        for (const op of Object.keys(this.operationLimits)) {
          const opLimit = this.operationLimits[op];
          const opTimePassed = now - opLimit.lastRefill;
          const opSecondsPassed = opTimePassed / 1000;
          const opTokensToAdd = Math.floor(opSecondsPassed * opLimit.maxTokens);
          
          if (opTokensToAdd > 0) {
            opLimit.tokens = Math.min(opLimit.maxTokens, opLimit.tokens + opTokensToAdd);
            opLimit.lastRefill = now;
          }
        }
      }
    }
    
    // Check minute-based limits
    for (const op of Object.keys(this.minuteLimits)) {
      const minuteLimit = this.minuteLimits[op];
      if (now >= minuteLimit.resetTime) {
        minuteLimit.count = 0;
        minuteLimit.resetTime = now + 60000;
      }
    }
  }
  
  /**
   * Queues a request with promise resolution
   * @param {Function} requestFn - Function that returns a promise for the API call
   * @param {Object} options - Queue options
   * @param {string} [options.operationType='read'] - Type of operation ('read' or 'write')
   * @param {string} [options.resourceType=null] - Type of resource (e.g., 'database', 'page')
   * @param {boolean} [options.priority=false] - Whether this request has priority in the queue
   * @param {string} [options.requestId=null] - For logging correlation
   * @returns {Promise<*>} - Promise that resolves with the API response
   */
  queueRequest(requestFn, options = {}) {
    // Skip rate limiting if disabled
    if (!this.enabled) {
      return requestFn();
    }
    
    const operationType = options.operationType || 'read';
    const resourceType = options.resourceType || null;
    const priority = options.priority || false;
    const requestId = options.requestId || null;
    
    return new Promise((resolve, reject) => {
      const request = { 
        requestFn, 
        resolve, 
        reject, 
        operationType,
        resourceType,
        requestId,
        attempts: 0,
        maxAttempts: 5,
        queuedAt: Date.now()
      };
      
      if (priority) {
        this.queued.unshift(request);
        if (requestId) {
          logger.debug('Added priority request to queue', { 
            operationType, resourceType, queueLength: this.queued.length 
          }, requestId);
        }
      } else {
        this.queued.push(request);
        if (requestId) {
          logger.debug('Added request to queue', { 
            operationType, resourceType, queueLength: this.queued.length 
          }, requestId);
        }
      }
      
      if (!this.processing) {
        this.processQueue();
      }
    });
  }
  
  /**
   * Processes queued requests if tokens are available
   * @private
   */
  async processQueue() {
    if (this.processing || this.queued.length === 0) {
      return;
    }
    
    this.processing = true;
    
    try {
      this.refillTokens();
      
      // Find the next request that can be processed based on token availability
      let requestIndex = -1;
      
      for (let i = 0; i < this.queued.length; i++) {
        const request = this.queued[i];
        
        // Check if we have overall tokens available
        if (this.tokens <= 0) {
          break;
        }
        
        // Check operation-specific tokens
        const opLimit = this.operationLimits[request.operationType];
        if (opLimit && opLimit.tokens <= 0) {
          continue;
        }
        
        // Check minute-based limits
        const minuteLimit = this.minuteLimits[request.operationType];
        if (minuteLimit && minuteLimit.count >= minuteLimit.max) {
          continue;
        }
        
        requestIndex = i;
        break;
      }
      
      if (requestIndex === -1) {
        // No eligible requests, wait for token refill
        this.processing = false;
        return;
      }
      
      // Process the request
      const request = this.queued.splice(requestIndex, 1)[0];
      this.tokens--;
      
      // Update operation-specific tokens
      const opLimit = this.operationLimits[request.operationType];
      if (opLimit) {
        opLimit.tokens--;
      }
      
      // Update minute-based limits
      const minuteLimit = this.minuteLimits[request.operationType];
      if (minuteLimit) {
        minuteLimit.count++;
      }
      
      const waitTime = Date.now() - request.queuedAt;
      if (request.requestId && waitTime > 500) {
        logger.debug(`Request waited ${waitTime}ms in queue`, { 
          operationType: request.operationType,
          waitTime 
        }, request.requestId);
      }
      
      try {
        const result = await request.requestFn();
        
        // Update token info from headers if available
        if (result.headers) {
          if (result.headers['x-notion-rate-limit-limit']) {
            this.maxTokens = parseInt(result.headers['x-notion-rate-limit-limit'], 10);
          }
          
          if (result.headers['x-notion-rate-limit-remaining']) {
            this.tokens = Math.min(
              this.maxTokens, 
              parseInt(result.headers['x-notion-rate-limit-remaining'], 10)
            );
          }
          
          // Log rate limit headers for debugging
          if (request.requestId) {
            const rateLimitHeaders = {
              limit: result.headers['x-notion-rate-limit-limit'],
              remaining: result.headers['x-notion-rate-limit-remaining'],
              reset: result.headers['x-notion-rate-limit-reset']
            };
            
            if (rateLimitHeaders.limit || rateLimitHeaders.remaining) {
              logger.debug('Rate limit headers received', rateLimitHeaders, request.requestId);
            }
          }
        }
        
        request.resolve(result);
      } catch (err) {
        request.attempts++;
        
        // Handle rate limit errors
        if (err.response && err.response.status === 429) {
          const resetAfter = err.response.headers && 
            err.response.headers['x-notion-rate-limit-reset'] 
              ? parseInt(err.response.headers['x-notion-rate-limit-reset'], 10) * 1000
              : 1000;
              
          const message = `Rate limit hit for ${request.operationType} operation. Retrying after ${resetAfter}ms...`;
          
          if (request.requestId) {
            logger.warn(message, { 
              statusCode: 429, 
              resetAfter, 
              attempt: request.attempts,
              maxAttempts: request.maxAttempts
            }, request.requestId);
          } else {
            console.warn(`🚦 ${message}`);
          }
          
          // Adjust our tokens to 0 to respect the rate limit
          this.tokens = 0;
          
          if (request.attempts < request.maxAttempts) {
            // Re-queue the request with priority after waiting
            setTimeout(() => {
              this.queued.unshift(request);
              // Try processing the queue again
              if (!this.processing) {
                this.processQueue();
              }
            }, resetAfter);
          } else {
            const errorMessage = `Max retries (${request.maxAttempts}) exceeded for rate-limited request`;
            if (request.requestId) {
              logger.error(errorMessage, {
                statusCode: 429,
                attempts: request.attempts,
                maxAttempts: request.maxAttempts
              }, request.requestId);
            } else {
              console.error(`❌ ${errorMessage}`);
            }
            request.reject(err);
          }
        } else {
          // Other errors, just reject
          request.reject(err);
        }
      }
    } catch (error) {
      console.error('❌ Error in rate limiter queue processing:', error);
    } finally {
      this.processing = false;
      
      // Process more from queue if there are pending requests
      if (this.queued.length > 0) {
        setTimeout(() => this.processQueue(), 50);
      }
    }
  }
  
  /**
   * Gets statistics about the rate limiter state
   * @returns {Object} Object containing rate limit statistics
