import { ChromaClient, Collection } from 'chromadb';

// Create a test collection name with a random suffix to avoid collisions
export const getTestCollectionName = () => 
  `test_collection_${Math.random().toString(36).substring(2, 10)}`;

// Initialize a test ChromaClient
export const getTestChromaClient = () => {
  return new ChromaClient({
    path: process.env.CHROMA_DB_URL || 'http://localhost:8000',
  });
};

// Create a clean test collection for isolated tests
export const createTestCollection = async (
  collectionName?: string
): Promise<{ client: ChromaClient; collection: Collection; name: string }> => {
  const name = collectionName || getTestCollectionName();
  const client = getTestChromaClient();

  // Check if collection exists and delete it if it does
  try {
    const existingCollection = await client.getCollection({ name });
    if (existingCollection) {
      await client.deleteCollection({ name });
    }
  } catch (error) {
    // Collection doesn't exist, which is fine
  }

  // Create fresh collection
  const collection = await client.createCollection({
    name,
    metadata: { 
      'test': true,
      'created': new Date().toISOString(),
    },
  });

  return { client, collection, name };
};

// Clean up a test collection after tests
export const cleanupTestCollection = async (
  client: ChromaClient, 
  collectionName: string
): Promise<void> => {
  try {
    await client.deleteCollection({ name: collectionName });
  } catch (error) {
    console.warn(`Failed to clean up test collection ${collectionName}:`, error);
  }
};

// Generate random test embeddings
export const generateRandomEmbedding = (dimensions: number = 1536): number[] => {
  return Array(dimensions).fill(0).map(() => Math.random() * 2 - 1);
};

// Add test documents to a collection
export const addTestDocuments = async (
  collection: Collection,
  count: number = 5
): Promise<string[]> => {
  const ids = Array(count).fill(0).map((_, i) => `test-doc-${i}`);
  const documents = ids.map(id => `This is test document ${id}`);
  const embeddings = ids.map(() => generateRandomEmbedding());
  const metadatas = ids.map(id => ({ id, test: true }));

  await collection.add({
    ids,
    documents,
    embeddings,
    metadatas,
  });

  return ids;
};

// Run a test query against a collection
export const runTestQuery = async (
  collection: Collection,
  queryText: string = 'test query',
  topK: number = 3
) => {
  const queryEmbedding = generateRandomEmbedding();

  return collection.query({
    queryEmbeddings: [queryEmbedding],
    nResults: topK,
  });
};
