// Helper to compare two objects for approximate equality
// Useful when comparing objects with floating point values
export const expectObjectsToBeApproximatelyEqual = (
  actual: any, 
  expected: any, 
  tolerance: number = 0.0001
) => {
  expect(Object.keys(actual).length).toBe(Object.keys(expected).length);

  for (const key of Object.keys(expected)) {
    if (typeof expected[key] === 'number' && typeof actual[key] === 'number') {
      expect(actual[key]).toBeCloseTo(expected[key], Math.log10(1/tolerance));
    } else if (Array.isArray(expected[key]) && Array.isArray(actual[key])) {
      expect(actual[key].length).toBe(expected[key].length);
      for (let i = 0; i < expected[key].length; i++) {
        if (typeof expected[key][i] === 'number') {
          expect(actual[key][i]).toBeCloseTo(expected[key][i], Math.log10(1/tolerance));
        } else {
          expect(actual[key][i]).toEqual(expected[key][i]);
        }
      }
    } else {
      expect(actual[key]).toEqual(expected[key]);
    }
  }
};
