## 6. Next.js Integration

### 6.1 Setting up API Routes

Create an API route for ChromaDB operations:

```typescript
// src/app/api/memory/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getChromaClient } from '@/lib/chromadb-config';
import { getCollectionName } from '@/lib/memory/schema';
import { generateEmbedding } from '@/lib/embedding';
import { MemoryItem } from '@/types/memory';

export async function POST(request: NextRequest) {
  try {
    const { personalityId, item } = await request.json();

    if (!personalityId || !item || !item.content) {
      return NextResponse.json(
        { error: 'Missing required fields' }, 
        { status: 400 }
      );
    }

    const client = getChromaClient();
    const collection = await client.getCollection({
      name: getCollectionName(personalityId),
    });

    // Generate unique ID if not provided
    const id = item.id || crypto.randomUUID();

    // Generate embedding for the content
    const embedding = await generateEmbedding(item.content);

    // Prepare metadata
    const metadata = {
      timestamp: item.timestamp || new Date().toISOString(),
      category: item.category || 'general',
      importance: item.importance || 5,
      ...item.metadata,
    };

    // Add item to collection
    await collection.add({
      ids: [id],
      embeddings: [embedding],
      documents: [item.content],
      metadatas: [metadata],
    });

    return NextResponse.json({ success: true, id });
  } catch (error) {
    console.error('Memory storage error:', error);
    return NextResponse.json(
      { error: 'Failed to store memory' }, 
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  try {
    const searchParams = request.nextUrl.searchParams;
    const personalityId = searchParams.get('personalityId');
    const query = searchParams.get('query');
    const limit = parseInt(searchParams.get('limit') || '5');

    if (!personalityId || !query) {
      return NextResponse.json(
        { error: 'Missing required parameters' }, 
        { status: 400 }
      );
    }

    const client = getChromaClient();
    const collection = await client.getCollection({
      name: getCollectionName(personalityId),
    });

    // Query similar memories
    const queryEmbedding = await generateEmbedding(query);
    const results = await collection.query({
      queryEmbeddings: [queryEmbedding],
      nResults: limit,
      includeMetadata: true,
      includeDocuments: true,
    });

    return NextResponse.json({ 
      memories: results.documents[0].map((doc, i) => ({
        id: results.ids[0][i],
        content: doc,
        ...results.metadatas[0][i],
        relevance: 1 - (results.distances?.[0][i] || 0),
      }))
    });
  } catch (error) {
    console.error('Memory retrieval error:', error);
    return NextResponse.json(
      { error: 'Failed to retrieve memories' }, 
      { status: 500 }
    );
  }
}
```

