## 7. CRUD Operations Implementation

Let's create a comprehensive memory service for all CRUD operations:

```typescript
// src/lib/memory/memory-service.ts
import { getChromaClient } from '../chromadb-config';
import { getCollectionName } from './schema';
import { generateEmbedding } from '../embedding';
import { MemoryItem } from '@/types/memory';
import { ChromaMemoryOptions } from '@/types/chromadb';

export class MemoryService {
  private personalityId: string;

  constructor(personalityId: string) {
    this.personalityId = personalityId;
  }

  async getCollection() {
    const client = getChromaClient();
    return client.getCollection({
      name: getCollectionName(this.personalityId),
    });
  }

  /**
   * Store a new memory item
   */
  async createMemory(item: Omit<MemoryItem, 'id'>): Promise<string> {
    const collection = await this.getCollection();

    // Generate unique ID
    const id = crypto.randomUUID();

    // Generate embedding
    const embedding = await generateEmbedding(item.content);

    // Prepare metadata
    const metadata = {
      timestamp: item.timestamp || new Date().toISOString(),
      category: item.category || 'general',
      importance: item.importance || 5,
      ...item.metadata,
    };

    // Add to collection
    await collection.add({
      ids: [id],
      embeddings: [embedding],
      documents: [item.content],
      metadatas: [metadata],
    });

    return id;
  }

  /**
   * Retrieve memory by ID
   */
  async getMemoryById(id: string): Promise<MemoryItem | null> {
    const collection = await this.getCollection();

    const result = await collection.get({
      ids: [id],
      includeMetadata: true,
      includeEmbeddings: false,
    });

    if (!result.documents.length) {
      return null;
    }

    return {
      id,
      content: result.documents[0],
      timestamp: result.metadatas[0].timestamp,
      category: result.metadatas[0].category,
      importance: result.metadatas[0].importance,
      metadata: result.metadatas[0],
    };
  }

  /**
   * Update existing memory
   */
  async updateMemory(id: string, updates: Partial<Omit<MemoryItem, 'id'>>): Promise<boolean> {
    // First, get the existing memory
    const existing = await this.getMemoryById(id);

    if (!existing) {
      return false;
    }

    // For content updates, regenerate embedding
    let embedding;
    if (updates.content) {
      embedding = await generateEmbedding(updates.content);
    }

    const collection = await this.getCollection();

    // Update content if provided
    if (updates.content) {
      await collection.update({
        ids: [id],
        embeddings: [embedding!],
        documents: [updates.content],
      });
    }

    // Update metadata if any provided
    const updatedMetadata: Record<string, any> = {
      ...existing.metadata,
      timestamp: updates.timestamp || new Date().toISOString(),
      category: updates.category !== undefined ? updates.category : existing.category,
      importance: updates.importance !== undefined ? updates.importance : existing.importance,
      ...updates.metadata,
    };

    await collection.update({
      ids: [id],
      metadatas: [updatedMetadata],
    });

    return true;
  }

  /**
   * Delete memory by ID
   */
  async deleteMemory(id: string): Promise<boolean> {
    const collection = await this.getCollection();

    try {
      await collection.delete({
        ids: [id],
      });
      return true;
    } catch (error) {
      console.error(`Failed to delete memory ${id}:`, error);
      return false;
    }
  }

  /**
   * Search for similar memories
   */
  async searchMemories(
    query: string, 
    options: ChromaMemoryOptions = {}
  ): Promise<(MemoryItem & { relevance: number })[]> {
    const {
      maxResults = 5,
      minRelevanceScore = 0.7,
      includeSimilarityScore = true,
      metadataFilter,
    } = options;

    const collection = await this.getCollection();

    // Generate embedding for the query
    const queryEmbedding = await generateEmbedding(query);

    // Query the collection
    const results = await collection.query({
      queryEmbeddings: [queryEmbedding],
      nResults: maxResults,
      includeMetadata: true,
      includeDocuments: true,
      includeDistances: includeSimilarityScore,
      where: metadataFilter,
    });

    // Transform results
    const memories = results.ids[0].map((id, index) => {
      const distance = results.distances?.[0][index] || 0;
      const relevance = 1 - distance; // Convert distance to similarity score

      // Skip results below relevance threshold
      if (relevance < minRelevanceScore) {
        return null;
      }

      return {
        id,
        content: results.documents[0][index],
        timestamp: results.metadatas[0][index].timestamp,
        category: results.metadatas[0][index].category,
        importance: results.metadatas[0][index].importance,
        metadata: results.metadatas[0][index],
        relevance,
      };
    }).filter(Boolean) as (MemoryItem & { relevance: number })[];

    return memories;
  }

  /**
   * List all memories with optional filtering
   */
  async listMemories(
    filter?: Record<string, any>, 
    limit?: number
  ): Promise<MemoryItem[]> {
    const collection = await this.getCollection();

    const results = await collection.get({
      where: filter,
      limit,
      includeMetadata: true,
    });

    return results.ids.map((id, index) => ({
      id,
      content: results.documents[index],
      timestamp: results.metadatas[index].timestamp,
      category: results.metadatas[index].category,
      importance: results.metadatas[index].importance,
      metadata: results.metadatas[index],
    }));
  }
}
```

